insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('7183873','utility','7183873','US','2/27/2007','An impedance matching transformer is disclosed. The transformer includes a conductive ground plane and a dielectric substrate disposed upon the conductive ground plane. The dielectric substrate has a first end and a second end. The dielectric substrate may be of a unitary construction. A conductive current path is disposed upon the dielectric substrate. The height of the dielectric substrate at the second end is greater than the height of the dielectric substrate at the first end.','Tapered thickness broadband matching transformer','B1',7,'ipg070227.xml',0,'[-0.017406875,0.050955083,0.03987733,-0.047621664,0.01623743,0.011565083,-0.03520633,0.0011295358,0.04764849,0.01944086,0.0033915776,-0.011266503,0.06881242,-0.04165441,0.023453629,-0.0014044953,0.037437584,-0.051706016,-0.009078426,0.0078737065,-0.0060470607,-0.10827172,-0.10566213,0.013282157,0.020426719,-0.06575194,0.03169802,-0.026142888,-0.08188522,0.05717192,0.0045300224,-0.02583545,0.01842517,-0.022379262,0.014403524,-0.025613446,-0.004919307,-0.006939347,0.009063825,0.0051895073,0.044763535,0.024234638,-0.017190091,-0.013540633,-0.049212568,0.04187494,-0.03271701,0.034298897,0.02545279,-0.018254492,0.038207002,0.0381682,-0.023544954,-0.038644154,0.023931907,0.029506393,0.01274563,0.08577147,-0.016180202,0.0354905,0.026576705,-0.022697356,-0.03257345,-0.012200352,-0.022793649,0.047739968,0.03531115,0.030093879,0.038284954,-0.0016280354,-0.020717304,-0.03126689,0.025122961,-0.04595784,0.01627132,-0.025558501,0.074248955,-0.0152918305,-0.011832116,0.1081008,-0.01098061,-0.030350598,-0.030740226,-0.043778505,0.005249304,-0.011185082,0.010844288,-0.019820709,0.009722749,0.013937016,0.022742407,-0.017132608,-0.018718135,-0.0029438564,0.008139384,-0.019091781,-0.017137734,0.05960749,-0.0074724606,-0.0072861803,0.02390084,0.045