insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('6843495','utility','6843495','US','1/18/2005','A step device that can reduce sound and vibrations generated when it comes in touch with the ground. The step device includes a platform for placing the drivers foot thereon, and a bank sensor that projects from the platform and comes into contact with the ground when vehicle body is inclined. The platform and the bank sensor are integrally formed so that these members can be formed by casting. This configuration provides for a reduction of the sound and the vibrations which are generated when the step device comes in touch with ground.','Step device for a motorcycle','B2',19,'ipg050118.xml',0,'[0.010164879,0.02056764,0.012450964,0.0024430798,-0.009440641,0.051150113,0.037814654,-0.04050849,0.019690238,-0.019282036,-0.06290651,0.04932553,0.069789834,-0.04501641,0.029076567,0.050656583,0.07234144,-0.025106402,0.014104214,-0.09200726,0.032556836,-0.012236316,-0.044145156,0.06606622,-0.005211658,-0.07067844,0.011804541,-0.043041915,-0.033551503,0.08063575,0.0149350455,-0.08592546,-0.043145612,-0.08404773,0.042254686,-0.09374746,0.03132847,0.026267879,0.021529155,0.04280456,0.0400152,-0.04912141,-0.012998695,-0.05872489,-0.037139636,-0.0060179853,0.0013308616,0.018983295,-0.010754723,-0.04182161,0.0012268217,0.041561734,0.027448665,-0.037193254,0.009723118,0.07029187,0.02862117,0.017655658,-0.022934621,-0.0040201903,-0.027612366,-0.0682597,-0.044240702,-0.020446833,-0.02243411,0.053059477,-0.0011083997,-0.013741895,0.03264976,-0.010739512,0.016326256,0.020040365,-0.0029073716,-0.03583359,-0.041467436,-0.0027905072,-0.027290387,0.053273357,-0.044672348,0.0377912,-0.0037460453,-0.018257555,-0.07509729,0.017216222,-0.018436395,-0.06791152,0.0026317732,-0.045224477,0.014367093,0.020429278,-0.0027759587,-0.017254842,-0.012546724,-0.036803227,0.03840721,0.04116017,0.05231466,0.088008635,-0.