insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('9457996','utility','9457996','US','10/4/2016','A balustrade support for an escalator or moving walk is located in a deflection area of the balustrade handrail. The support has a mounting region for mounting a handrail deflection wheel, a first fixing section for mounting the support to a framework of the escalator or moving walk, and a second fixing section for mounting the support to the balustrade. The rigidity of the supports mounting region for the deflection wheel is increased by the mounting of the support to the framework as well as to the balustrade.','Balustrade support for an escalator or a moving walkway','B2',13,'ipg161004.xml',0,'[0.011122625,0.01301676,0.015362506,-0.04035941,0.028571555,0.049595326,0.029755265,-0.03298143,0.07058508,-0.060628504,-0.036820695,0.001237021,0.072402015,-0.024963727,0.048955966,0.011369743,0.038757026,-0.066318475,-0.019645253,0.00339033,0.03456174,-0.010539774,-0.034415096,0.005946905,0.07089891,-0.070272304,0.046855357,-0.027584713,-0.049157187,0.046859186,-0.025773479,-0.051909354,0.07356641,0.0031891316,0.034631085,-0.015168316,0.041637734,-0.016259082,0.003341587,0.0051133,0.041952163,-0.06113369,-0.0045279604,-0.085682414,0.009583138,0.009867404,0.018887093,0.05203675,0.01843617,-0.050280336,0.02909513,0.03227301,0.01961939,-0.009630827,0.025341596,0.079820305,0.022205267,0.04904605,-0.049897306,-0.029352758,0.023733813,0.003349095,0.0045648734,-0.02390962,-0.05281364,0.056952156,0.0008160926,-0.012646384,0.0404049,-0.050580498,0.041810513,-0.051011235,0.011463901,-0.028289922,-0.011126834,-0.04077881,0.0026319262,0.0048736236,-0.021261416,0.051628806,-0.040611587,0.00528418,-0.027895216,-0.06337531,-0.016922405,-0.07790126,0.015897041,-0.038986895,0.034397587,0.05719545,0.0058899387,-0.03380741,0.05027075,-0.027316323,0.063659914,0.057410512,-0.008903675,0.07396641,0.01474418,