insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('5350066','utility','5350066','US','9/27/1994','A palletized container system including deck and runner structure formed from a unitary deck sheet of corrugated material having top and bottom generally planar surfaces and opposite parallel sides. The deck sheet is folded downwardly and then upwardly at each of its sides to form fore-and-aft extending outer runners unitary with the remainder of the sheet to provide outer runner lateral stability. An elongated central runner is fixed to the bottom of the sheet and extends parallel to the outer runners. A corrugated wrapper extends under the central and side runners and is folded around the side runners and over the deck sheet. The wrapper has upper planar portions extending inwardly from the side portions of the side runners toward the central runner and fixed to the top planar surface. A one-piece liner board is fixed to the upper planar portions of the wrapper to increase strength and includes flaps folded upwardly to slidably receive an open bottom container.','Corrugated pallet and container system','A',17,'pftaps19940927_wk39.zip',0,'[-0.0074508656,0.021196293,0.04510835,0.00023617575,0.059278995,0.053982563,-0.0126968995,0.023584496,0.025937805,0.023781795,-0.023666706,0.013252976,0.058083426,-0.047851548,0.03896388,-0.010127077,0.02785114,-0.034077816,-0.0040048603,0.017961342,0.0041928613,-0.089632295,-0.045559127,0.0057271365,0.038207002,-0.0948683,0.030874051,-0.0032652318,0.0023247958,0.00070194306,0.008914705,-0.04381951,0.060774814,-0.015050014,0.028788,-0.011049084,0.0052136057,0.040652428,0.033523392,0.029280107,0.08047018,-0.027784824,-0.0026786348,-0.060578752,-0.042845253,0.04204845,0.0077977628,-0.011264929,0.048734423,-0.053705223,0.012983082,0.06813082,-0.015175399,-0.042991553,0.018303316,0.018853175,0.012342508,0.059085503,-0.03656713,0.0011498743,0.0065358