insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('9474822','utility','9474822','US','10/25/2016','A sterilization and deodorization apparatus is provided. The sterilization and deodorization apparatus may include a frame that defines an outer appearance of the sterilization and deodorization apparatus, a plasma unit or device disposed on or at one or a first side of the frame, the plasma unit forming a plasma region to generate a plurality of ions, and a filter unit or filter disposed on the other or a second side of the frame which is spaced apart from the frame. The filter unit may include a filter frame having a plurality of through-holes so that air passes therethrough, and a photocatalyst applied to the filter frame to perform photocatalytic reaction.','Sterilization and deodorization apparatus','B2',20,'ipg161025.xml',0,'[-0.018294208,0.017762447,0.038709912,-0.04128682,-0.026608001,0.06804332,0.024085898,0.02063786,0.024387049,0.054967772,0.02657161,-0.02665562,0.007501907,-0.08159533,0.029979965,0.005412079,0.035392474,-0.07094331,0.041622285,0.013624653,-0.041187104,-0.078280136,-0.0045382776,0.027198333,0.06697289,-0.07643511,-0.019387579,-0.016738474,-0.020348392,0.02206796,0.038829204,-0.06375023,0.04913547,-0.024765776,-0.0061621433,-0.011746205,0.0437182,0.006081017,0.0148788225,-0.003986402,0.05800472,-0.03748412,0.05599714,-0.019728009,-0.035139125,0.02920794,-0.021592718,0.049971875,0.018669246,-0.0753498,0.045283463,0.048586898,0.018922469,-0.06077304,0.032522943,0.032332562,0.0059230025,0.05601103,-0.0055165566,-0.024192682,0.001376698,-0.042473126,-0.018802073,0.01613876,-0.01646511,0.09686632,0.034791756,0.038516898,-0.027265845,-0.029690761,-0.009479254,-0.022276744,0.024178373,-0.033966593,0.0007849569,-0.001082741,-0.006371745,0.015311315,-0.012340441,0.045388132,-0.065429874,-0.04042881,-0.014717981,0.002921013,-0.001829262,-0.008955691,-0.00984373,0.