insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('9474899','utility','9474899','US','10/25/2016','A portable device for treating the bites or stings of insects and harmful creatures, comprising a monolithic containing body made in a single piece and defining an internal housing space, a piezoelectric element configured for producing a predetermined difference in electrical potential, and an actuating element operable by a user and associated with said piezoelectric element to impart to the piezoelectric element a predetermined state of stress/deformation; the actuating element, the piezoelectric element and the discharge area are aligned along the operating axis. The monolithic containing body presenting a bottom part developing along the operating axis below a guide and housing portion, the bottom part defining part of the internal housing space with an overall span orthogonal to the operating axis which is constantly smaller than an overall span of the internal housing space defined by the guide and housing portion.','Portable device for treating insect bites and the like','B2',20,'ipg161025.xml',0,'[-0.024944905,-0.001533035,0.014539465,-0.057880513,-0.05073371,0.028855933,0.00091856165,-0.046465818,0.0156202745,-0.0108809,-0.058290027,-0.00436115,0.019298,-0.06720638,0.029197212,0.029445136,0.064539686,-0.095313914,0.008819265,-0.037268594,-0.024318298,-0.056523938,-0.06899105,0.03474021,0.06088359,-0.08636619,0.042592227,-0.03920998,-0.018617745,0.08301169,-0.020463897,-0.014249952,0.024479618,-0.03402855,0.04053605,-0.014646916,0.026684776,0.024760121,-0.009194356,-0.0030009437,0.036632847,-0.051104777,0.050911177,-0.015664566,0.040509384,0.0058541256,-0.032030944,0.023743967,0.007304752,-0.06459534,0.010108887,0.035656694,-0.04377336,-0.07133633,0.0376576,0.007024958,0.0035575856,0.06973202,0.013277784,0.029891245,-0.026716061,-0.018863833,-0.02971052,0.014533586,-0.01