insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('9476502','utility','9476502','US','10/25/2016','A hydraulic pressure supply system of an automatic transmission for a vehicle is disclosed. The hydraulic pressure supply system of an automatic transmission for a vehicle may supply a low hydraulic pressure generated at a low-pressure hydraulic pump to a low pressure portion through a low-pressure regulator valve, may supply a portion of the low hydraulic pressure to a high-pressure hydraulic pump, and may supply a high hydraulic pressure generated at the high-pressure hydraulic pump to a high pressure portion through a high-pressure regulator valve.','Hydraulic pressure supply system of automatic transmission','B2',20,'ipg161025.xml',0,'[0.028364472,0.057410188,0.0078010354,-0.016711205,0.031940486,0.0030449887,0.050950345,0.009677787,0.01400662,-0.040179156,-0.015556213,-0.007707925,0.04832225,-0.03303653,0.015081489,-0.015435936,0.034013107,-0.04841564,-0.019410046,-0.037653472,0.01345222,-0.057105538,-0.04126265,0.063532636,-3.5038698e-05,-0.048076514,0.0012323731,-0.012964185,-0.048165835,0.014961348,0.0384649,-0.04637495,0.06743022,-0.0012076534,0.002537723,-0.013317624,-0.017531443,-0.03616029,0.012749419,-0.00060295005,0.018854776,-0.070849925,-0.0011315608,-0.010578214,-0.03636251,0.07761965,-0.015111624,-0.0010868788,0.016630568,-0.013579025,0.0072839665,0.03182304,0.065179974,0.018309109,-0.033229645,-0.020330315,0.06107159,0.005584824,-0.009247031,0.012946078,-0.026870333,-0.04133461,0.002470008,0.018218225,-0.06957667,0.08368177,0.015607415,-0.0015152431,0.020604433,-0.02321375,-0.038845968,-0.0013770544,0.035807442,-0.053420592,-0.02445653,-0.059360035,0.06159316,0.030009992,-0.078515515,0.05413945,-0.04582499,-0.03946875,-0.051128875,0.034336068,0.049761586,-0.09666222,-0.05303634,-0.015364967,0.02663087,0.011125744,0.008002329,-0.0067484584,0.035137337,-0.0405058