insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('9477213','utility','9477213','US','10/25/2016','A sheet processing apparatus is described which is used to process a sheet transferred from an image forming apparatus such as a copying machine. A sheet processing apparatus is provided with a punching unit which cuts off part of a sheet conveyed along a conveying route, and a humidifying unit located on this conveying route in the upstream side of the punching unit and configured to humidify a predetermined area which is selected from the entire area of the sheet and includes punch areas to be cut off from the conveyed sheet by the punching unit. The cutting wastes can thereby be electrostatically discharged without leaving the sheet excessively wet.','Sheet punching device with humidifier','B2',11,'ipg161025.xml',0,'[-0.01903644,0.017307496,0.061644312,-0.05350217,0.020891499,0.04779288,0.0015328663,0.01809374,-0.021814356,-0.034016337,0.00448076,-0.026910743,0.050936013,-0.07748343,0.07164577,0.025681857,0.04909394,-0.09032487,-0.0046609226,0.019441443,0.018187482,-0.0362746,-0.0068042693,0.016208468,0.06858069,-0.0738552,-0.029035864,-0.020720353,-0.078255035,0.068218455,-0.026397748,-0.053241037,0.061016783,-0.010660037,0.032237142,0.003995955,0.0319228,2.1528198e-05,0.06630958,0.040726885,0.0692195,-0.0446482,0.023351781,-0.028439056,-0.03109876,0.010342572,0.00489026,-0.008168541,0.112261064,-0.04236803,-0.013327553,0.044408824,-0.0088838115,-0.026150765,0.05131262,0.014547445,0.00033791744,0.0678914,-0.0069665518,-0.032065958,-0.027439922,-0.050713196,0.004093057,0.022899013,-0.040103436,0.04109192,-0.0015091804,-0.05428799,0.004709048,-0.09765735,-0.0083805015,0.019024894,0.0160989,-0.061697043,0.0017764891,-0.033318467,-0.0026897583,0.039113164,-0.008215735,0.10225207,-0.08611503,-0.070636705,-0.065170705,0.015637971,0.043524098,-0.0070940214,0.023968993,-0.0071759373,