insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('6855894','utility','6855894','US','2/15/2005','A mobile lifting device comprises a mobile frame (1, 12, 13) with a set of lift forks (3) for receiving a pallet thereon. The pallet truck is provided with a weighing device which comprises at least one pressure or strain-sensitive sensor (20) in addition to a display panel (21) for indicating thereon a value measured by the sensor. The sensor is connected firmly to a pan (12) of the frame and able to determine a mechanical deformation in that part of the frame. The weighing device comprises this sensor.','Mobile lifting device and weighing device therefor','B1',11,'ipg050215.xml',0,'[-0.027878666,-0.03390126,0.00056284264,0.0120288115,0.0054687224,0.034453165,0.024629029,-0.015606216,0.009737886,0.013940526,-0.0456527,-0.025540251,0.058482293,-0.046836052,0.060077805,-0.029375294,0.027076265,-0.065939665,-0.009526727,-0.046235688,0.026040323,-0.0613735,-0.043373737,0.018918494,0.023755344,-0.013375104,-0.0015605994,-0.032199107,-0.046303958,0.013870321,-0.0073201237,-0.062544584,0.015776623,0.004082056,0.06184036,-0.011623094,0.07529544,0.024130592,0.017854732,-0.0062051844,0.06522099,-0.06599239,-0.019838432,-0.075116985,-0.013599373,0.024883738,-0.013147543,-0.008407446,0.026569098,-0.037876934,0.015138891,0.077791944,0.022375358,-0.017327892,0.00490613,0.014615326,0.00060108164,0.033576354,0.0019113886,0.030691676,-0.012396399,-0.01582061,0.010624569,0.013451967,-0.04077336,0.048879176,-0.00216365,0.034271315,0.010911266,-0.07606723,0.0022844297,-0.061428234,0.0019651232,-0.049672313,-0.0654563,-0.08321039,-0.0105170375,-0.008243102,-0.063594036,0.037674714,-0.021745268,-0.027026948,-0.06435938,-0.02262258,-0.028113928,-0.05422174,-0.0012872148,0.0149423815,0.014174343,0.046440274,0.0041638482,-0.0075742393,0.03949988,-0.03324134,0.02079769,-0.02940878,-0.023835732,0.08723301,