insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('9479968','utility','9479968','US','10/25/2016','A base station device includes: a control information generating section which generates control information specific to mobile station devices; a control information count indicator generating section which generates a control information count indicator indicating the number of pieces of generated control information of each mobile station device; and a transmitting section which transmits the control information count indicator and the control information. The mobile station device includes: a receiving section which receives a control information count indicator and control information transmitted from the base station device within a mobile station-specific search space selected based on a mobile station ID of the mobile station device; a control information count indicator detecting section which detects the control information indicator; and a control channel decoding section which decodes the control channel in response to the number of pieces of detected control information.','Wireless communication system, mobile station device, and base station device','B2',10,'ipg161025.xml',0,'[0.0010754267,0.0038848282,0.039546944,0.00049833715,0.020610165,0.028921722,0.036102746,0.016113108,0.028672727,-0.027192213,-0.0012519504,0.0052080224,0.09832137,-0.05757382,0.057818815,-0.036613815,0.027214516,-0.05110779,-0.030871462,-0.028066227,0.028423315,-0.07584527,-0.03140893,0.024162835,0.0176124,-0.08417988,-0.009781858,-0.018164275,-0.06984625,0.027751239,0.014542802,-0.028552711,0.061814465,0.026986241,0.02591342,-0.07083151,0.02829895,-0.016845264,0.06418574,-0.043387197,0.014346798,-0.012995617,0.03824242,-0.049215257,-0.036388326,-0.023743998,-0.06891512,-0.0056549385,0.039779954,-0.029772496,0.033177346,0.02781013,-0.015882373,0.008876817,-0.0241349,-0.022830704,0.009242841,0.