insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('9487008','utility','9487008','US','11/8/2016','A multichannel printhead is proposed having an array of fluid ejectors for applying a liquid coating material to a surface, characterized in, that each fluid ejector includes a fluid valve with a closing element such as an actuated membrane 8 or an actuated valve seal 11, interacting with a valve seat 10 connected to the valve opening 9, the fluid valve controlling the flow of the liquid coating material through the valve opening 9, that the valve opening 9 enters into multiple fluid outlets 6, that the fluid outlets 6 of all of the fluid ejectors are arranged within a regular array of at least one row, that the fluid ejectors are actuated as to discharge discrete amounts of the liquid coating material through the fluid outlets 6 to the surface according to the drop-on-demand principle, whereas the valve seats 10 and valve openings 9 of at least one fluid ejector are part of a first plate and the fluid-outlets 6 of at least one fluid ejector are part of a second plate.','Multichannel multinozzle printhead','B2',11,'ipg161108.xml',0,'[-0.0071607125,-0.020201417,0.0351242,-0.03349954,-0.0146396635,0.023364788,-0.009473037,0.035263494,0.042886145,-0.053090684,-0.065911636,-0.043048147,0.049688973,-0.059987,0.052886266,-0.021157762,0.047943622,-0.08644353,-0.003714283,-0.023971196,0.02791019,-0.07305975,-0.031386197,0.021041473,0.068705685,-0.061527856,-0.010157589,-0.020820256,-0.049561214,0.047021743,0.022799388,-0.012770676,0.045664653,-0.00294951,0.013555707,-0.015589874,0.022172576,0.013805037,0.014667573,0.011102483,0.08240288,-0.010172986,0.03310969,-0.043918766,-0.044321347,0.025081787,-0.046042215,0.023158994,0.054728042,-0.05952479,0.01607442,0.07514457,0.0017995464,-0.0068593966,0.03187286,0.020465294,0.020273082,0.06835379,-0.0018497268,0.008247995,-0.02921669,-0.04739748,