insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('9487275','utility','9487275','US','11/8/2016','Method and vessel for performing marine acoustic survey of a subsurface. The vessel includes a launching module configured to deploy an autonomous underwater vehicle (AUV) underwater; a recovery module configured to recover the AUV; a homing device mounted on the recovery module and configured to guide the AUV to the recovery module; and a management module connecting the launching module to the recovery module and configured to transport the AUV.','Deployment and recovery vessel for autonomous underwater vehicle for seismic survey','B2',17,'ipg161108.xml',0,'[-0.009787526,0.005864876,0.060328137,0.0064255903,-0.00021672949,0.022386441,-0.03968675,-0.030011404,0.039703306,0.027059883,-0.02255049,-0.017653896,0.057281297,-0.07089198,0.019176474,0.025076358,0.022489049,-0.012104575,0.003241758,-0.06864868,0.013643479,-0.041520044,-0.07896928,0.047546152,0.037084524,-0.05932162,0.031507693,-0.030862585,-0.055944882,0.023165395,0.010355878,-0.050040886,0.06058826,-0.03004967,-0.011316589,0.012818105,0.04516193,0.01700216,-0.021797292,0.018783962,0.022969136,-0.042424444,0.055204958,-0.029844439,-0.0027634772,0.041776102,-0.048137616,0.041168027,0.012160354,-0.047897983,0.02008061,0.050035886,0.0177152,-0.030339796,0.0073451926,0.043735173,0.0203587,0.0013670209,0.011808255,0.021517927,0.035625,-0.012962046,0.036919907,-0.006030088,-0.072693296,0.11455418,0.025490914,0.046634313,0.02404397,-0.044168137,-0.023230553,-0.063453265,0.08262774,-0.068654664,-0.062688984,0.018679244,0.03374271,-0.03389209,-0.034254618,0.046401687,-0.032502905,-0.048408657,-0.050256822,0.060419574,0.07035721,-0.038707674,-0.0151974475,-0.078168124,-0.045798756,-0.0011971608,0.036890503,0.057735167,-0.0018115301,0.019346025,0.07629523,0.052231964,-0.06474058,0.12135782,-0.013880595,0.060983483,0.020070564,0.020