insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('9487692','utility','9487692','US','11/8/2016','Methods of treating a wellbore in a subterranean formation including providing a treatment fluid comprising a consolidating agent, wherein the consolidating agent comprises the reaction product of a furfuryl alcohol or a furfuryl alcohol derivative and a silicon derivative compound selected from the group consisting of a siloxane; a silane; a silanol; a silsesquioxane; any derivative thereof; and any combination thereof; introducing the treatment fluid into the wellbore in the subterranean formation; contacting the consolidating agent with a surface of the wellbore in the subterranean formation; and setting the consolidating agent.','Methods for consolidation treatments in subterranean formations using silicon compounds derived from furfuryl alcohols','B2',8,'ipg161108.xml',0,'[-0.015297814,0.00678773,0.002737264,-0.056098357,0.05249288,0.031990446,0.039900333,0.057264607,0.004137735,-0.015197068,-0.015068554,-0.02120038,0.024875432,-0.043279532,0.04668507,0.008624821,0.044114344,-0.081806354,0.04915432,-0.013117926,0.046230685,-0.03866324,0.010824209,0.047782034,-0.0029458003,-0.053445436,-0.002430544,0.010223511,-0.030361364,0.018717743,0.04102624,0.022961354,0.1282321,-0.01842784,0.0017010823,0.006755429,0.050989434,0.029988414,0.041054185,0.037781302,0.05209775,0.0014476198,0.038172036,0.0013118072,0.011351558,0.02007206,0.0019543886,0.02780869,0.04238267,-0.048603013,0.07132257,0.028768713,-0.00096278783,0.02546341,0.08607513,0.03420229,0.05648399,0.018678663,0.016527472,-0.01410432,0.01732995,-0.077495866,-0.049633212,-0.07226666,-0.020172045,0.06846672,0.016848817,0.08447686,0.014048306,0.016666945,-0.0069025494,-0.028224457,0.053748854,-0.022407653,-0.08977394,-0.04767927,0.014804736,0.010320871,-0.0030543022,0.05404538,-0.023566505,0.010200012,0.019180622,-0.018413238,0.0