insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('9488866','utility','9488866','US','11/8/2016','An optical laminate having layer A having a resin having a negative intrinsic birefringence and at least one layer B having a transparent resin, having substantially no orientation and laminated at least on one face of layer A and satisfies a relation |Re(A)|>|Re(B)|, wherein Re(A) and Re(B) represent in-plane retardations of layer A and layer B, respectively, measured with light having a wavelength of 400 to 700 nm, an optical element having a laminate of the optical laminate and a polarizer plate, and a liquid crystal display device using at least one sheet of the optical laminate. In the liquid crystal display device, optical compensation can be made in accordance with the mode of the liquid crystal display by the three dimensional control of the refractive index, and the liquid crystal display device provides an image display with liquid crystals exhibiting small change in the phase contrast depending on the viewing angle.','Optical laminate, optical element and liquid crystal display device','B2',20,'ipg161108.xml',0,'[0.016801639,-0.010516542,0.019508297,0.012080704,-0.022509754,0.0521997,-0.027432555,-0.011224022,0.043686356,-0.037485924,-0.04526617,0.031296905,0.02482759,-0.052903283,-0.006769029,-0.034271292,0.031566754,-0.066304386,-0.038908046,0.018796885,0.015199429,-0.0537749,-0.09885985,0.02199478,0.000981138,-0.063272156,0.018671453,-0.014957688,-0.057392195,0.071712755,0.049743533,-0.015149959,0.05454017,0.008149495,0.023126783,-0.052874852,0.031682253,0.014691488,0.024509143,-0.007940559,0.048722498,-0.08231769,0.001730367,-0.048774242,-0.080387615,0.053455226,-0.071048826,-0.0244964,0.04694052,-0.012954108,-0.0032963485,0.002758793,0.013207999,-0.028419025,0.04753361,0.026383236,0.017252143,0.048236698,-0.034218896,-0.018852018,0.010434365,0.01449849,0.024026403,