insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('6872118','utility','6872118','US','3/29/2005','A frictional-type game calling apparatus, wherein a striking plate is adapted to be frictionally contacted by a striker for reproducing the mating, gathering, and feeding calls of wild turkeys. The present apparatus and method allows for easy, one-handed operation, wherein the striker is held in constant contact with the striking plate, thereby allowing unrestricted use of the game call in any physical orientation.','Game call device','B1',22,'ipg050329.xml',0,'[-0.06522316,0.017363958,-0.01610637,-0.03449339,0.004873791,0.041662704,0.014912065,-0.026748253,0.047332563,-0.043375645,-0.001661692,0.039301433,0.030887043,-0.099961974,-0.002312559,0.050300214,0.046274967,-0.07962196,-0.020783866,-0.04610035,0.04060357,-0.02859677,-0.078784905,0.053939354,-0.012378509,-0.07425737,0.0242846,0.004813312,-0.034016274,0.07903813,-0.0036373874,-0.03962131,-0.002303069,-0.044276282,-0.011820796,-0.015499973,-0.0021297336,0.016667122,0.060106322,0.025679914,0.03915613,-0.07135096,-0.033708412,-0.0018058011,0.03487173,0.046903882,-0.023414057,-0.0021467125,0.04671001,-0.05253216,0.03422316,0.06980785,-0.011463025,0.02197295,0.041111715,-0.009451697,0.024051644,0.04476143,-0.0067001684,-0.0032844981,0.013835984,-0.06891653,-0.044808798,-0.017808445,-0.027273512,0.12185069,0.06415815,0.012357311,-0.046158336,-0.04964979,0.026141506,-0.046202365,0.03312604,-0.03362665,-0.052748658,0.0050834618,-0.0013668498,0.07183863,-0.03166069,0.014316499,-0.0052424246,0.00031870877,-0.09928481,-0.021779869,0.0022213368,-0.044219445,-0.018141765,-0.056861263,-0.046557724,0.024096984,2.774779e-05,-0.045424536,-0.014623097,0.020211993,0.029975051,0.058806293,0.004102332,0.085028104,0.04000232,0.04840904,0.044203356,0.037437253,0.043326184,-0.039991595,-0.009382679,0.045489386,-0.012332517,0.023949653,0.054839343