insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('6845597','utility','6845597','US','1/25/2005','A compact form-fill-seal machine capable of the high speed production, collation and loading into cartons of a variety of small dispensing packages with instant opening features including fault lines in the lower containment formation. It can make a variety of formations in the upper cover member as well as fault lines. It also produces simple cups and tubs. The machine operates at extremely high efficiency with practically every known thermoformable plastic film.','Compact form-fill-seal machine','B2',17,'ipg050125.xml',0,'[0.022796158,-0.044488404,-0.020539004,-0.038100652,0.036389466,0.0034349046,-0.0127984835,0.02176213,0.026355147,0.04320425,-0.05233686,-0.053995416,0.03256209,-0.07911336,0.02863391,-0.0017979324,0.07597766,-0.059564307,0.040929157,-0.0025346803,-0.0060232454,-0.061158672,-0.015780665,0.027127042,0.009774143,-0.07141615,-0.013026381,-0.002113897,-0.016553082,0.023875518,0.003929083,-0.047446348,0.04903394,-0.06328319,0.0009475285,0.013207562,0.01256014,0.04613783,0.010213685,-0.011796311,0.079148136,-0.05157414,-0.007394871,-0.058728434,-0.05223342,0.016779419,-0.013405381,0.020398365,0.08392532,-0.057256736,-0.0033237915,0.07514256,-0.03197171,-0.032610808,0.06141984,0.013629742,0.03679648,0.042716365,-0.020475082,0.018808497,-0.012835293,-0.045231767,-0.05254767,0.027508562,-0.08143705,0.076550245,0.0771213,-0.024808917,-0.013873942,-0.07105642,-0.06012838,-0.0070714313,-0.012801944,-0.047548797,-0.0052468693,-0.022402206,0.010672479,0.035481475,-0.052990727,0.08887271,-0.043128666,-0.03309259,-0.06682482,0.011227619,0.043499917,-0.00057393993,-0.02964656,-0.039714627,0.008485752,0.03555238,0.0010094994,0.020939274,0.017275425,-0.02590344,-0.025316011,-0.0068774624,0.019583123,0.066268206,0.02540972,0.05743383,0.014165223,0.014651839,-0.017313536,-0.0264345