insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('6846569','utility','6846569','US','1/25/2005','A carbon-doped hard mask includes a dielectric material containing carbon which is released from the hard mask during a metal etching process. The released carbon is deposited on and bonds to sidewalls of the metal structure during the metal etching process to passivate the sidewalls of the metal structure and prevent lateral etching of the sidewalls during the metal etching process. The released carbon also prevents accumulation of metal residue in open fields.','Carbon-doped hard mask and method of passivating structures during semiconductor device fabrication','B2',6,'ipg050125.xml',0,'[0.01288279,-0.000675633,-0.0062991227,-0.01211004,-0.002741955,0.12389725,-0.026024662,0.045873564,0.017346222,-0.04540069,-0.00443975,-0.04556594,0.050525542,-0.050797045,0.02956826,-0.015485332,0.054779302,-0.053317454,0.024076896,-0.010639106,0.043740124,-0.06913561,-0.05111172,0.010240751,0.02761893,-0.078316785,-0.044725057,-0.028394992,0.04894908,0.08732373,0.0012314809,-0.0014562547,0.047650997,-0.010124641,0.018553296,-0.038526706,0.029716702,0.018829225,-0.0031318066,0.013693997,0.054649774,-0.015969831,0.028078156,0.025777476,-0.048449624,0.028495882,-0.045885954,-0.007918146,0.04741442,-0.048360646,-0.06633018,0.062251087,-0.0021045688,-0.06939976,0.029598592,0.04426943,0.028288495,0.069541104,-0.014254921,-0.0027182067,0.018775716,-0.030780084,-0.04627877,0.022445671,-0.03205144,0.043707695,0.04388805,0.021303864,-0.024596792,-0.0057855737,-0.04211667,-0.00067847915,0.037428837,0.018651897,0.0061982917,0.05347343,0.018765073,0.047244858,-0.011584226,0.06919875,-0.04482005,-0.02318432,-0.07720173,-0.007837029,0.045901954,-0.026027517,0.00024103453,-0.028571744,-0.007928753,-0.004777844,0.0061094984,-0.05112794,0.035084717,0.019545723,-0.035019834,0.012618149,-0.013374197,0.064539485,0