insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('6859025','utility','6859025','US','2/22/2005','A method and apparatus for measuring quantities of a multi-phase electric line, the apparatus comprising a control unit and a measurement unit in connection with each phase conductor of the electric line, wherein each measurement unit is arranged to measure a first phase quantity of the phase conductor in connection with which it is located and to transfer the measured quantity value to the control unit, the measurement unit located in connection with one phase conductor being further arranged to measure phase angles between the first phase quantity of said phase conductor and first phase quantities of other phase conductors and to transfer the measured phase angle values to the control unit.','Measurement of quantities of electric line','B2',20,'ipg050222.xml',0,'[0.010739333,0.009800215,0.018001923,0.007475802,0.056360263,0.04666433,0.07052998,-0.0005825321,0.03014278,-0.02529366,-0.046291392,-0.021877307,0.04285936,-0.05078578,0.026631564,-0.01908561,0.040933337,-0.053133518,-0.057865284,-0.00086927816,-0.0009245509,-0.093087696,-0.06831264,-0.015370566,0.006079282,-0.022786668,-0.022605546,-0.020398336,-0.049072094,0.02327192,-0.032552935,-0.02820088,0.08420973,0.0076287617,0.05960276,0.009102786,0.027841084,-0.0061549707,-0.024233684,0.0050309994,0.031669606,-0.017466933,0.002515509,-0.046998914,-0.028472228,0.006536896,-0.081067674,-0.022065133,-0.03631279,-0.032128144,-0.015626136,0.047745153,0.028796686,-0.012428027,0.006518939,0.04087408,0.0006353764,0.054529615,-0.005455995,0.08260664,0.021042867,-0.051475517,0.03510133,0.042419787,-0.052847285,0.047087286,0.022244986,0.08253279,0.046284005,-0.03092603,-0.022629684,-0.06023617,0.058619186,-0.046799652,-0.0036140182,-0.02245545,0.0058097774,-0.10910875,-0.067945465,0.066130824,-0.039015893,-0.037933044,-0.040394433,-0.053