insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('6859129','utility','6859129','US','2/22/2005','A three dimensional adjustable high frequency inductor, its module and fabrication method of the same. The high frequency module includes micro high frequency inductors, filters, resistors, capacitors and associated with active components or power components to form a hybrid circuit, then it is packaged by using the technology of flip chip or wafer level packaging, so as to upgrade properties of high frequency modules and reduce the packaging and instrumentation costs by minimizing the modular size.','Three-dimensional integrated adjustable inductor, its module and fabrication method of the same','B2',15,'ipg050222.xml',0,'[0.027344434,0.019219415,0.04119768,-0.0658771,0.005104242,0.06470997,-0.037444152,-0.053518724,0.07773863,-0.029477788,-0.05097499,-0.012662853,0.054399434,-0.052410614,-0.00365856,-0.045864325,0.017622668,-0.09520428,-0.01402061,0.023994949,-0.026038228,-0.10509362,-0.03368391,0.056131124,-0.004041006,-0.071853325,-0.056836385,-0.0034951565,-0.037330545,0.08399288,-0.0010677252,-0.045397267,0.049044628,-0.04720543,-0.009681746,-0.04370666,-0.015129864,0.027965711,0.002536443,-0.01305657,0.04103485,-0.07121952,0.00856493,-0.024165513,-0.021324432,0.07766639,-0.05394431,-0.0016755282,0.05004166,-0.01297324,0.037318982,0.02435825,-0.023226561,-0.027364442,0.022215849,0.036428105,0.014725847,0.019570956,-0.04470737,0.07305113,0.006592322,-0.07712881,0.016462816,0.030483425,0.05357332,0.043131113,-0.013658111,0.025747443,0.05145326,-0.0021130189,-0.022791406,0.013623755,0.04986231,-0.039634254,0.038221676,0.026475385,0.031598352,-0.017275464,0.001753153,0.039179366,-0.06803289,-0.066942096,-0.032282677,0.054441612,0.033966232,-0.016428174,-0.03380945,0.033328183,0.001808841,0.033712238,0.02280397,0.0065652193,-0.007636906,-0.030233238,0.023905165,0.029281745,-0.009