insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('6861041','utility','6861041','US','3/1/2005','A method for treating and upgrading effluents containing at least a metallic sulphate comprising adding at least a base to the effluent to precipitate the metallic ions in the form of iron oxy-hydroxides Fe(OHx) wherein x=2 and/or 3; separating the precipitated hydroxide calcium sulphate CaSO4; and separating the calcium sulphate CaSO4 precipitated during the preceding step. Said method enables obtainment of calcium sulphate (white gypsum) substantially free of metals and therefore capable of being upgraded and iron oxy-hydroxides likewise capable of being upgraded.','Method for treating and upgrading effluents containing metallic sulphates using an ammonia addition step','B2',6,'ipg050301.xml',0,'[0.011694844,-0.0045527224,-0.019908689,-0.017842544,0.047576334,0.03404094,0.03266888,0.041858125,-0.02660865,0.01645568,-0.031353798,-0.008905981,0.017147928,0.012017088,0.045681626,0.054385204,0.037637707,-0.0575191,0.03015368,0.025171848,0.05463048,-0.060628694,0.03390868,0.035529226,0.013515185,-0.054531015,-0.025858423,0.038539533,-0.038235012,-0.02071495,0.026542727,0.0003588441,0.0755605,-0.08575655,0.0055753365,0.018531958,0.08620649,-0.010898169,0.06587751,0.028894719,0.038939178,0.018612562,0.0121583305,-0.022349255,-0.012885197,0.02690479,0.010551902,0.012512653,0.061610587,-0.061550334,0.052157283,0.008096668,-0.055190865,-0.015709246,0.058397315,0.039857745,0.059886973,0.028101048,0.024324981,-0.063653626,0.008847967,-0.06953986,0.050815232,-0.021070339,0.020413563,0.046775363,0.06954148,0.04522493,0.02139914,-0.024801496,0.021641511,-0.03291123,0.07688157,-0.006636714,-0.05297836,-0.02502261,0.0005821655,0.044987164,0.029395452,0.0013181634,-0.027879067,-0.00012330165,-0.011477335,0.014704105,-0.014040414,-0.053817943,-0.025628434,-0.046840336,0.012547538,0.02729644,-0.0356