insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('5046256','utility','5046256','US','9/10/1991','A method of operating an automatic drafter for producing a long drawing having successive parts, in which, after drawing on a long sheet a preceding frame of the drawing corresponding to a preceding part of the long drawing, the area in which the next frame is to be drawn is expanded by moving the leading edge of the area to form a portion overlapping the trailing portion of the preceding frame. Then the lines of the trailing portion of the preceding frame which are to extend across the junction between the successive parts of the sheet in the overlapping portion are redrawn and then continued in the next frame while drawing the remainder of the lines in the next frame on the sheet in the remainder of the area in which the next frame is to be drawn.','Method of connection drawing in automatic drafter','A',1,'pftaps19910910_wk37.zip',0,'[0.0112797385,-0.02951137,0.010451409,0.0127623975,0.06336754,0.021917816,0.031892784,0.0040104752,0.01801978,-0.061854772,-0.057524685,0.0016815531,0.085426554,-0.05707223,0.068851896,0.033993,0.001952297,-0.014454784,0.0011977054,0.0039960365,0.001433099,-0.039021745,-0.014805801,-0.004767378,0.032117162,-0.07646515,-0.019440541,-0.015546346,-0.037009824,0.037808955,-0.039520074,-0.04816397,0.059632316,0.011290315,0.025594555,0.049802203,0.026434286,-0.005592921,0.030900292,0.03069061,0.05066511,-0.02954076,-0.008617496,-0.011374906,-0.06295176,0.022731641,-0.022949561,0.042554867,0.026642349,-0.046659566,-0.048569042,0.06890262,0.015788123,0.010312985,0.030315014,0.016007766,0.030382682,0.014058186,-0.053870637,-0.059423428,-0.038501885,0.036299054,0.01745307,0.00827297,-0.07378781,0.051986117,0.019284979,0.00068284647,-0.0020369121,-0.06683455,-0.026682569,-0.041022368,0.041902177,-0.096098855,0.02985926,-0.029070213,0.020825034,-0.062112045,-0.