insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('8483242','utility','8483242','US','7/9/2013','A method and apparatus for processing inter-RAT measurement in a dual modem device are disclosed. A method for processing inter-RAT measurement in a dual modem device includes receiving, by a first processor communicating with a first communication network, a measurement control signal including a parameter for signal measurement from the first communication network; transmitting, by the first processor, timing information based on a system frame number (SFN) and a global time to a second processor; acquiring time synchronization for the inter-RAT measurement between the first processor and the second processor on the basis of the system frame number (SFN) and the global time; transmitting the parameter from the first processor to the second processor; and measuring, by the second processor, a signal of a second communication network using the parameter.','Method and apparatus for processing inter-rat measurement in dual modem device','B2',10,'ipg130709.xml',0,'[-0.029059784,-0.027028022,0.029330052,-0.005330212,0.006135451,0.023909898,-0.007652295,-0.070578456,0.062235296,-0.06403186,0.0148230465,-0.01962344,0.041792955,-0.079993114,0.07251714,-0.052609336,0.0012283882,-0.057330884,-0.048749045,-0.029388228,0.01226708,-0.030629603,-0.03784866,0.03774034,-0.008006739,-0.058051594,0.010419225,-0.029442508,-0.0853174,0.032262973,-0.03491255,-0.03058579,0.015129462,0.011822384,0.008097723,-0.037286248,0.02546952,-0.024325175,0.096929505,-0.035527676,0.045425057,0.021256844,0.0036669853,-0.018082011,-0.02941349,-0.008782486,-0.07579254,0.024139155,-0.02449329,0.010591023,0.024523076,-0.011070632,0.01628818,0.0076651005,0.0194129,-0.016072618,-0.021504417,0.060275458,0.02732927,0.024859848,-0.01370706,-0.0341742,0.04309669,0.02453738,-0.082619324,0.052520365,0.016630989,0.079570904,0.00