insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('5045384','utility','5045384','US','9/3/1991','A polyester laminated film comprising a polyester inner layer having a density greater than 1.3 g/cm.sup.3 and polyester outer layers on both sides of said inner layer having a density in the range of 0.4 to 1.3 g/cm.sup.3 is disclosed. The laminated film of this invention has high discrimination property and is also improved in image printability on the film surface in comparison with the conventional polyester films. When, for instance, the present laminated film is used as base for prepaid cards, which is a preferred application of the present film, it contributes to the enhancement of security of the cards, and it also enables high-quality printing by thermal transfer method.','Polyester laminated film','A',7,'pftaps19910903_wk36.zip',0,'[-0.026136205,0.0062198243,-0.00854893,-0.029671,0.046844594,0.026476957,-0.0052018957,0.009356698,0.012142091,-0.020675186,-0.026614347,-0.006416109,0.013499213,-0.01716433,0.054710947,-0.020036532,0.036446907,-0.035780743,-0.022491883,0.039841518,0.019687237,-0.078184344,-0.029191049,0.03024466,-0.026090616,-0.08017231,0.012319593,-0.0033809606,-0.03829342,0.020362137,-0.007547493,-0.057732254,0.019135423,0.004524769,-0.029898142,-0.028971508,0.026418827,-0.09373718,0.080492355,-0.011268976,0.03681136,0.006434358,0.0050269063,-0.06309804,-0.04695651,0.039997354,-0.0128858965,0.0006437906,0.04227429,-0.040645137,-0.024347274,0.028968936,-0.01514499,-0.037065715,0.052069955,-0.08225217,-0.004879494,0.041308444,0.024207426,0.01137557,-0.02015742,0.037506953,0.025564644,0.07054409,-0.03912103,0.08970436,0.019734085,-0.026676564,0.055447824,-0.062651984,-0.00052597694,-0.0112688495,-0.007582446,-0.040758047,0.032003947,-0.02997912,0.017963968,0.045687832,-0.02396259,0.067995295,-0.07669084,-0.034439042,-0.06905551,0.004480838,0.014801804,-0.050529