insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('10663553','utility','10663553','US','5/26/2020','Systems, methods, and devices for intra-scan motion correction to compensate not only from one line or acquisition step to the next, but also within each acquisition step or line in k-space. The systems, methods, and devices for intra-scan motion correction can comprise updating geometry parameters, phase, read, and/or other encoding gradients, applying a correction gradient block, and/or correcting residual errors in orientation, pose, and/or gradient/phase.','Methods, systems, and devices for intra-scan motion correction','B2',20,'ipg200526.xml',0,'[0.027160924,0.0015465233,0.03911026,-0.015249757,-0.016345378,0.098910436,-0.0020893926,0.00074397033,0.10176701,-0.01887667,-0.0040857038,0.0016433704,0.07374374,-0.069659315,0.052959923,-0.025040455,-0.007608409,-0.06386231,-0.041654304,-0.0036014721,0.026898403,-0.0186704,-0.04877614,0.038943984,-0.008030906,-0.073825315,-0.035576038,-0.0033307755,-0.003512045,0.05053563,-0.03628064,-0.0489453,0.10328688,0.012034278,0.027965039,-0.022579363,0.0079570105,0.022275625,0.0018708896,0.016600685,0.030207727,-0.061650723,0.03604997,0.0013463772,-0.0446482,0.041981567,-0.062196575,-0.01631578,0.030684665,-0.083565645,-0.037477292,0.012033495,0.023673886,-0.0098062,0.004917918,0.037024453,0.051588528,0.02028838,0.0019945141,0.011009801,0.02620504,-0.03856932,0.06094373,0.004857724,-0.024719594,0.03819143,0.017063452,-0.0022808365,0.054449987,-0.029226268,0.020886794,0.006779933,0.081157714,-0.046022486,0.0074060974,-0.028712196,0.06677741,-0.041026335,-0.01809676,0.056854583,-0.028956473,-0.048564035,-0.033897657,0.015489742,0.066438705,0.00828112,-0.031625073,-0.018817035,0.020711316,0.018191215,-0.026280567,0.02528656,0.016024468,-0.050143197,0.027745213,0.049441624,0.0030668105,0.13681403,0.025138754,-0.0072619533,-0.055074967,0.00638