insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('5049021','utility','5049021','US','9/17/1991','An unloading marine leg for a self-unloading ship including a bucket conveyor for removing granular material from the hold of a ship, the marine leg including a distal end and a discharge end with the discharge end being pivotally mounted to a carriage on a travelling bridge on the deck of the ship. The travelling bridge includes tracks extending athwartship on which the carriage is mounted for athwartship movement and the marine leg can pivot between a vertical position with the distal end near the bottom of the hold and a rest position with the marine leg parallel with the travelling bridge.','Self-unloading method and apparatus for ships','A',2,'pftaps19910917_wk38.zip',0,'[0.006065402,-0.019979464,-0.006188267,-0.050779827,0.058077972,0.011345715,0.00054815796,0.019089771,0.016540477,0.04501377,-0.039847195,0.005517033,0.1071315,-0.023906125,0.07897348,0.04368838,-0.02787243,-0.04282547,0.007977637,-0.04314408,0.04031235,-0.03241489,-0.03264273,5.300368e-05,0.050515246,-0.04239529,0.008482251,-0.038954582,-0.055922806,-0.007038589,0.0068235225,-0.03695562,0.068192184,-0.03184601,0.027522415,0.022919927,0.031821147,0.00224823,0.026175907,0.038347933,0.081980534,-0.043685887,0.01279428,-0.024515064,-0.024790501,-0.006755121,0.00958564,0.010641515,0.049409043,-0.0854807,0.02314923,0.056132127,-0.010461274,0.005418393,0.03393185,0.047376387,0.032431357,0.008931562,-0.044325177,0.03785623,-0.00038878262,-0.017784765,0.035273716,0.010676039,-0.014964176,0.05735243,0.008374635,0.0067046313,-0.0012592616,-0.076361574,0.02806762,-0.056742128,0.04420117,-0.08630383,-0.011885289,-0.061115768,0.05223008,0.018651063,-0.058046047,0.083589934,-0.0017820473,-0.063069694,-0.044324793,-0.0032685804,0.005761995,-0.057373177,0.023997687,-0.04570169,-0.0057351594,0.013179373,0.0016330512,0.0025163