insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('5051734','utility','5051734','US','9/24/1991','Special effects using polar image coordinates produce a new class of television special effects, such as spherical mapping and kaleidoscope effects. Rectangular coordinates for an input image are converted into polar coordinates, and the polar coordinates are mathematically manipulated according to the desired special effect. The modified polar coordinates may be applied directly to the rectangular coordinates to produce modified rectangular coordinates that represent the desired special effect, or they may be converted back into rectangular coordinates as the modified rectangular coordinates.','Special effects using polar image coordinates','A',19,'pftaps19910924_wk39.zip',0,'[0.0033870228,0.01617033,0.027463416,-0.041339956,-0.03484364,0.06724924,0.02675245,0.019999731,0.102203965,-0.0040069134,-0.017563602,0.009544661,0.07361412,0.005027369,0.008342908,0.0014465513,0.04653642,-0.099112384,0.0010462652,-0.019154767,-0.0102052875,-0.019048465,-0.012576551,0.029014347,-0.0052413116,-0.05055489,0.012511151,-0.0066457638,-0.0011763982,0.045617383,0.0024635629,-0.034712426,0.059648063,0.07017534,0.03472346,-0.07142338,-0.005987006,0.0056492593,0.040564336,0.010588353,0.03258505,-0.03148297,-0.04245307,-0.038462065,-0.09488702,0.073025495,-0.06720338,0.014109575,-0.018333308,0.013758266,-0.010062935,0.0061624516,0.031121336,-0.014506815,0.014776476,0.06596454,0.04943448,-0.01639632,0.04499884,-0.028084945,0.037594117,-0.031356797,0.029276382,0.06993327,-0.077998586,0.047351416,0.010830673,0.0015420356,0.0325189,-0.0324378,-0.02279712,-0.028251404,0.05873694,-0.04652518,0.021269877,-0.044521324,0.038096707,0.0059019653,-0.0066476036,0.058776636,-0.06209017,-0.0075791804,-0.037289504,-0.014653853,0.045789797,-0.0107903015,-0.04026992,0.027615447,-0.026440427,-0.008416864,0.022757215,-0.