insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('10006494','utility','10006494','US','6/26/2018','This torque transmission mechanism (1) includes a transmission mechanism portion (2) that includes an input shaft (21), an output shaft (22), and an intermediate portion (23) including a connection portion (23b). The torque transmission mechanism includes a limiting mechanism portion (3) that is capable of switching between a connection state where the limiting mechanism portion is connected to the connection portion and limits rotation of the intermediate portion and a disconnection state where the limiting mechanism portion is disconnected from the connection portion and allows the rotation of the intermediate portion, and switches to the disconnection state when torque of at least a predetermined value acts in the connection state.','Torque transmission mechanism','B2',15,'ipg180626.xml',0,'[0.0041924776,0.021782178,0.024802878,-0.0004556655,0.045698293,0.04395774,0.015958294,-0.04868161,0.026914103,-0.024552424,-0.039381657,0.016508518,0.061570298,-0.06514442,0.05338356,-0.0034854875,0.06339704,-0.07334833,-0.010234955,-0.061696976,0.009364417,-0.067535706,-0.017438699,0.030155478,-0.0150597645,-0.102710225,-0.009256667,-0.017806143,-0.051178277,0.01712133,-0.020304365,-0.068715766,0.06809305,0.019284116,-0.00656407,-0.0684997,0.0047352393,-0.017631952,-0.016992588,0.01096501,0.06887862,-0.028919393,0.03269247,-0.021416532,0.00018214114,0.035206538,-0.04561594,0.03362993,0.07567145,-0.025546448,0.0011006381,-0.0038470547,0.008473078,-0.025621103,0.0061623594,0.022047937,0.0051445942,0.01712822,-0.020628251,0.009866187,-0.025867213,-0.040531907,0.024862066,-0.031494386,-0.04553965,0.0451827,0.0014662726,-0.022578351,0.027643126,-0.023876721,-0.010655429,-0.046108942,0.016244045,-0.030968837,-0.040328432,-0.011478406,0.013122549,-0.0011492067,-0.09991697,0.055196114,-0.0643854