insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('5053082','utility','5053082','US','10/1/1991','A system for cleaning solids contaminated with solvent-soluble contaminants. The system, which includes both process and apparatus, comprises slurrying of the solids with a solvent, feeding the slurry to a cyclone separation zone integrally connected to a countercurrent extraction zone, separating the slurry into an overflow stream which includes solvent and fine particles of solids and an underflow stream which includes mostly coarse particles of solids in the cyclone separation zone, processing the overflow stream in a cleaning zone with additional solvent, processing the underflow stream in countercurrent relationship with additional solvent through the countercurrent extraction zone, combining the cleaned coarse particles of solids withdrawn from the extraction zone with the cleaned fine particles of solids withdrawn from the cleaning zone and centrifuging the combined cleaned particles to remove residual solvent and recovering the combined solids having reduced contamination for disposal.','Process and apparatus for cleaning particulate solids','A',38,'pftaps19911001_wk40.zip',0,'[0.024051573,-0.024519075,-0.023220723,-0.05460775,0.047127586,0.048595846,0.008147912,0.027953766,0.0206668,-0.024438914,-0.025147894,-0.033904128,0.042964846,-0.037041403,0.051501784,0.0018509452,0.03189772,-0.06328486,0.060133904,0.013538865,0.0015919529,-0.03462863,0.004766082,0.06987266,0.041572113,-0.08391975,-0.024068732,-0.0006093097,-0.10852098,0.005270425,0.04355496,0.009679564,0.06255305,-0.08494871,0.032280818,-0.00035553094,0.036545776,0.011352641,0.038950197,0.021584526,0.08475978,-0.03754418,0.014860116,-0.055867262,-0.04595694,0.018456656,-0.013958141,-0.012498942,0.07250774,-0.09603271,0.041054875,0.006452571,0.027549246,-0.035304002,0.028555598,0.08303349,0.041433368,0.04352195,0.01