insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('5054146','utility','5054146','US','10/8/1991','A method of making an anchor bolt with a thread on a section thereof comprising the steps of providing a metal bar (1) of circular or near circular cross-section having a diameter which is substantially equal to the pitch diameter of the thread to be provided thereon, extruding the bar along a selected section (A) thereof to reduce its cross-section, forming a series of lateral protrusions (3) on the selected section of the bar, straightening the bar, and, forming a thread (5) with the said pitch diameter on a further selected section of the bar.','Anchor bolt','A',8,'pftaps19911008_wk41.zip',0,'[-0.053556986,0.040508293,-0.0159312,-0.044477154,0.04440852,0.047123652,0.027858356,0.011760915,0.035655193,-0.055136275,-0.09631017,0.028334236,0.036851164,-0.033482604,0.027514523,0.014243305,0.016269108,-0.06523344,-0.039920505,-0.061491735,0.016382191,-0.008768662,-0.0029721274,-0.0028267496,0.061986145,-0.06303416,-0.020238912,-0.012701196,-0.028122412,0.061285608,-0.014325222,-0.022794299,0.058515165,0.04715163,0.052130718,0.0066737784,0.021322455,-0.0799764,0.012157379,0.03025517,0.021160541,-0.01637199,0.021811297,-0.0176266,-0.015953317,0.030502757,-0.019196434,0.075350754,0.04030049,-0.03694983,0.046515863,0.03508345,-0.016003953,-0.08936811,0.044287004,0.049423017,0.021274367,0.00695783,-0.034651663,-0.043567445,0.015892893,-0.008383658,0.025552003,-0.028222656,-0.06439769,0.023910139,0.008340048,0.021077013,0.01952693,0.019587187,-0.011989006,-0.067573965,0.032109763,-0.0054090167,-0.058173176,-0.068550825,-0.028702747,0.044896465,-0.00019466445,0.08573998,-0.0403107,0.015943393,0.007570359,-0.052706644,0.034654487,-0.026107226,-0.016409911,-0.043321017,0.038409013,0.017992897,-0.026375443,-0.0056883497,0.042645905,-0.05801627,0.033646807,0.017249698,-0.020478502,0.05259398,0.