insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('5056737','utility','5056737','US','10/15/1991','A vertical take-off and landing aircraft is configured so as to provide, when landing tail-first with its fuselage (1) in a generally vertical attitude, a touchdown area (21) at the tail of the aircraft at a position offset from a line extending along the length of the fuselage through the centre of gravity (23) of the aircraft such that after the touchdown area contacts a landing surface the aircraft topples under the action of gravity to bring an undercarriage (11, 13) of the aircraft into contact with the landing surface, thereby to attain a stable landed position.','VTOL aircraft with movable undercarriage','A',11,'pftaps19911015_wk42.zip',0,'[-0.01796277,0.009447031,0.04211596,-0.034483798,0.03835244,0.038135897,-0.025827546,-0.05497847,0.018620947,-0.07332378,-0.029647492,-0.012768196,0.11176714,0.0033644354,0.029750144,0.017504536,-0.0030190628,-0.04561311,-0.020278769,-0.029235946,-0.0019958748,-0.055981737,-0.039116975,0.05889092,0.05326553,-0.0849705,0.042184502,-0.019531162,-0.07957283,0.081998855,-0.020610176,-0.042968888,0.043096177,0.010289533,0.0499166,-0.0010092345,0.01216759,0.009784434,-0.007253009,0.034175195,0.086729854,-0.030035751,-0.02197057,-0.030356385,-0.019180587,0.014947121,0.009344844,-0.038768362,0.051758565,-0.10937102,0.03114583,0.007929122,0.036224943,0.013656116,-0.01256648,0.07240991,0.0070753396,0.0115220435,-0.042991858,0.011386058,-0.020676672,0.011832193,0.0033596233,-0.017623866,-0.026744911,0.02096048,0.025317274,-0.037216153,0.006915014,-0.030736689,0.045519,-0.03434745,0.035846293,-0.0037918182,-0.021698298,-0.035423532,-0.01968149,-0.013883814,-0.0026759545,0.060114436,-0.007990035,-0.00939462,-0.032176804,0.01154944,-0.010237027,-0.035935413,0.05222418,-0.05553946,-0.03911005,-0.032744218,0.017495476,0.006968439,0.01807169,0.017871346,