insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('5059428','utility','5059428','US','10/22/1991','The present invention pertains to synergistic sweetening compositions which comprise Polydextrose and a chlorodeoxysugar derivative. The synergistic sweetening compositions may be used in a wide variety of ingestible products such as chewing gum composition, hard and soft confections, beverages, and the like. The present invention also pertains to methods for preparing the synergistic sweetening compositions and the ingestible products in which they may be used.','Synergistic sweetening compositions containing polydextrose and a chlorodeoxysurgar and methods for preparing same','A',26,'pftaps19911022_wk43.zip',0,'[-0.0015858489,-0.015222719,0.011078683,-0.040548928,0.040586848,0.04612786,-0.0048759775,0.01237757,0.023865646,-0.026499474,-0.040030673,0.003865232,0.06190206,-0.11839107,0.07418289,-0.005957069,-0.0037113708,-0.05961573,0.03511232,0.041319788,0.06488506,-0.07269423,-0.053385325,0.01757911,-0.010104398,-0.088985756,0.0075596008,-0.039060127,-0.036335886,0.0151268365,0.07860159,0.021115957,0.09960669,0.028050475,0.034278892,-0.019353323,0.0920579,-0.02399086,0.005908302,0.007944987,0.05794674,-0.058752526,-0.050037906,-0.039751288,-0.0076381518,0.02121918,-0.028872399,-0.0011018958,0.057214167,0.02763584,0.02313166,0.010454185,-0.016793955,-0.022593971,0.0549228,-0.00359312,-0.005743925,0.02982031,-0.018762039,0.008185448,0.0020083548,-0.025553465,-0.0052907635,0.005539848,-0.03989008,0.044698983,0.06691902,0.03595439,0.018027535,-0.005613358,-0.042719066,-0.014756365,-0.04238903,-0.028427735,0.01603674,-0.044181034,-0.016206317,0.039637998,0.028450737,0.06899352,-0.072938964,-0.05163479,-0.05733,-0.044618644,-0.02587331,-0.06488269,-0.046955794,-0.0058424626,-0.05078917,0.03472451,-0.0542769,0.0015141065,0.052551735,0.043723032,-0.006252256,0.010030896,0.062909685,0.0