insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('10683217','utility','10683217','US','6/16/2020','The systems and methods described herein relate to use of a reverse diffusion system for removal of dissolved ions from a fluid, for example, salt ions. Specific embodiments include a system for desalinating salt water to produce potable water. The systems and methods can include pulsing low levels of electricity via electrodes in a scrolling pattern, so as to sweep the ions across a unit.','Reverse diffusion desalination','B2',19,'ipg200616.xml',0,'[0.030382136,-0.032255717,-0.010096874,-0.041579366,0.011979843,0.04563325,-0.0019645207,0.08975516,0.035055254,0.012390361,-0.003964263,-0.04525144,0.060976952,-0.07717912,0.046323854,0.026148362,0.032961983,-0.06654147,-0.019777387,0.012464552,-0.026720619,-0.037636433,-0.05019565,0.02240238,0.03996932,-0.05832355,0.010062417,-0.018248778,-0.04713075,0.019654024,0.040858563,-0.025272185,0.05782703,-0.056957006,0.024309497,-0.014533531,0.044863474,0.009497433,-0.01472819,-0.036603853,0.05213651,-0.009099875,0.019354612,-0.026706195,0.00405299,0.022012116,-0.042149357,0.012359603,0.068861395,-0.013323312,-0.0057213544,0.012481183,-0.017014548,-0.04770071,0.01788367,0.028888859,-0.0044700094,0.07702134,-0.021798477,0.002578672,0.0032232716,-0.018971305,-0.0016699053,0.0005757937,-0.05136094,0.059586782,0.026323963,0.014672854,0.032376815,-0.047892556,-0.05790694,-0.042116705,0.066418774,-0.05921231,0.007819369,-0.040851925,0.017289022,0.030321928,0.043948345,0.05128585,-0.07065209,-0.0477308,-0.02674708,0.026964698,0.01149585,-0.0016747325,0.009331305,-0.0064826594,0.025581598,0.034629036,0.01839502,-0.05930211,0.044086028,-0.040233046,0.0032681217,0.061442822,0.02280371,0.061143342,0.0069948183,0.049976923,0.057444517,-0.015936611,0.011889519,-0.0018243449,-0.015066457,0.01357034,0.011956104,0.008759862,0.04807377,-0.028612861,-0.015