insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('5060470','utility','5060470','US','10/29/1991','A rocket motor or other gas generator the case of which is ventable at a predetermined temperature substantially greater than the ambient temperature range for storage and operation thereof and substantially less than the auto-ignition temperature of gas generant material contained therein so as to prevent catastrophic propulsion or burst in case of fire. The venting is provided by memory metal members which are interleaved between plies of matrix-impregnated fibrous material in the case and which have a transformation temperature which is substantially higher than the ambient temperature range and substantially lower than the auto-ignition temperature and characterized by a change in shape when heated to a temperature above the transformation temperature.','Gas generator ventable at a high temperature for hazard reduction','A',4,'pftaps19911029_wk44.zip',0,'[-0.05852395,0.0252032,0.06618135,-0.056972962,-0.027358774,0.025177635,0.006941249,-0.010625692,0.034581214,-0.007588749,-0.018040445,0.022578187,0.04818878,-0.10964403,0.04090126,0.0141015835,0.084655955,-0.07383683,0.036314826,-0.019543367,0.00850486,-0.11413795,0.008411107,0.0402301,-0.020434823,-0.07962514,0.013765084,-0.0034211986,0.027232371,0.031438336,-0.05822455,-0.0652092,0.10320331,0.027343215,0.011069621,-0.011326216,0.035004754,0.027322713,0.037008397,0.008514995,0.026170246,0.021406848,0.03300746,-0.031109547,0.0033630833,0.046526436,-0.031734496,0.0034960597,0.0663916,-0.037444886,0.03156787,0.06268452,-0.0031616539,-0.03490869,0.013290048,0.037226133,0.016875308,0.045232892,-0.046395753,0.014255555,-0.023921847,-0.021422485,-0.03568992,0.008056747,-0.03130979,0.049978577,0.07860143,-0.008662315,0.009836954,0.0214213,-0.028891973,0.010936163,0.020407338,-0.06354293,0.0051077628,0.062297933,0.014919977,0.009647