insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('5061307','utility','5061307','US','10/29/1991','A crystallized glass having natural-marble-like surface patterns comprising 45 to 75 wt. % of SiO.sub.2, 1 to 25 wt. % of Al.sub.2 O.sub.3, 1 to 20 wt. % of CaO, 0.5 to 17 wt. % of MgO, 0.1 to 18 wt. % of BaO, 0 to 18 wt. % of ZnO, 1 to 15 wt. % of Na.sub.2 O, 0 to 7 wt. % of K.sub.2 O, 0 to 5 wt. % of Li.sub.2 O, 0 to 10 wt. % of B.sub.2 O.sub.3, 0 to 10 wt. % of P.sub.2 O.sub.5, 0 to 1 wt. % of As.sub.2 O.sub.3, and 0 to 1 wt. % of Sb.sub.2 O.sub.3, substantially free from nucleating agent, in which diopside type crystals are precipitated, and a method of producing the crystallized glass are disclosed.','Crystallized glass having natural-marble-like surface patterns and method of producing the same','A',2,'pftaps19911029_wk44.zip',0,'[0.028335601,-0.012634623,-0.0042549623,-0.01866772,0.0027756235,0.05219326,-0.0021338486,0.009803067,0.061037984,0.031035142,0.0002752744,0.037074324,0.025765114,-0.033778787,0.02579875,0.033499576,0.040488083,-0.08519085,-0.033457756,-0.029675668,0.061630376,-0.038456813,-0.021410387,-0.016676031,0.015650382,-0.08487255,-0.016613679,0.037645955,0.022088934,0.03940385,0.07611866,0.012124755,0.07153391,-0.030111328,0.03979362,-0.008996187,0.03472032,0.022866676,0.032385617,-0.019557761,0.0066019064,-0.026146984,-0.02247714,-0.0025505149,-0.03369236,0.056118306,0.0054361536,0.077054426,0.02468635,-0.03888371,0.019116333,0.0019517039,-0.07067892,-0.051803175,0.051750727,-0.0017066953,0.1079406,0.02368925,-0.00022047434,0.008898944,0.024109466,-0.028735537,0.0047973073,0.0068565267,-0.01662112,0.021893438,0.04624148,0.037937626,0.0071285455,-0.015311547,-0.017674675,-0.012912736,0.03065002,-0.014429644,0.031970277,-0.07444782,0.011519932,0.04571451,-0.02695531,0.06582341,-0.025071368,-0.03677474,0.047297325,-0.011949799,-0.014497907,-0.043472447,-0.05