insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('5064447','utility','5064447','US','11/12/1991','A process for separating and recovering organic vapors (e.g., chlorofluorocarbons) from a feed stream of organic vapors and air wherein organic vapors are present in the "window concentration" range being too high for conventional carbon adsorption and too low for efficient compression/condensation recovery. By passing the organic vapor and air feed stream through the feed side of a semipermeable membrane unit, a vapor depleted stream exiting the membrane unit can then be processed by conventional carbon adsorption while a vapor enriched stream from the membrane unit can be processed by conventional compression and condensation.','Process for recovering organic vapors from air','A',11,'pftaps19911112_wk46.zip',0,'[-0.011679449,-0.032101296,0.018685028,-0.060182776,0.02920067,0.01835876,-0.009866685,0.060140755,-0.008777228,0.0045651407,-0.025227057,-0.024295703,0.04510179,-0.036652125,0.038540374,0.012361361,0.048442412,-0.06488857,0.027352381,0.00024114572,0.016271971,-0.09993749,0.010126936,0.044071496,0.029169936,-0.09697622,-0.006671219,-0.019948456,-0.020304142,0.012419103,0.025320342,-0.05606239,0.038501915,-0.046420548,-0.0029065101,-0.0062387553,0.034682006,0.015504962,0.0016305594,-0.0033053695,0.06816921,-0.038437817,0.029303025,-0.043635316,-0.09158685,0.03169543,-0.028337123,0.0005847587,0.07823442,-0.063128375,0.0011483405,0.023227548,-0.0003492675,-0.023266993,0.0052990257,0.014129718,0.026800757,0.07356395,-0.015398876,0.023620086,-0.0346526,-0.010533514,-0.016579766,-0.0071607167,-0.08017277,0.08222199,0.06648775,0.02465945,0.011495727,-0.021302277,-0.051434968,0.006643253,0.08776964,-0.07492449,0.017629208,-0.008502692,0.03828409,0.034417905,-0.019947557,0.052552152,0.006005035,-0.06506346,-0.07984908,-0.020084148,0.038449407,-0.009540631,-0.0017090599,-0.0681908