insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('5067941','utility','5067941','US','11/26/1991','The anti-motion sickness apparatus includes motion simulating means for providing a visually discernible wave motion image to create visually discernible orientation information for the user to confirm the inner ear information of the user, thereby preventing or at least greatly alleviating, the occurrence of motion sickness. A device helps position the motion simulating means in the field of view of the user. The method of use includes exposing the motion simulating means to the field of view of the user.','Anti-motion sickness apparatus','A',5,'pftaps19911126_wk48.zip',0,'[0.030547028,-0.0036199105,-0.0024681075,-0.08492487,-0.023580454,0.04791455,0.019284766,-0.046150647,0.049197048,-0.021224322,-0.014740712,0.05330479,0.0839326,-0.04764838,0.042162925,0.020742271,-0.01735989,-0.07038272,-0.010091965,-0.03694944,-0.016628895,0.029446017,-0.07194381,0.017803902,0.028680863,-0.058822744,0.021579674,-0.04276004,-0.068079464,0.051479936,-0.0046803197,-0.05767379,0.040185828,0.020362422,-0.0054396964,-0.04566223,0.027287854,-0.002989397,-0.009156552,-0.008862438,0.07813847,-0.0562344,-0.013974037,-0.05747904,-0.028770784,0.0217074,-0.015729561,-0.0055946577,0.03945614,-0.040702827,-0.042793773,0.03150912,0.032954242,0.00082297047,-0.0012745222,0.0171311,0.0030994487,0.08540029,-0.05302579,-0.032093454,-0.009427937,-0.020058792,0.04530055,0.0014227586,-0.05317313,0.058584426,0.009202801,0.0012325266,0.07464116,-0.056547455,0.07312473,0.0051930803,0.036003023,-0.0757065,-0.00020020267,-0.0043358775,0.028602313,-0.014266626,-0.04344546,0.078742504,-0.034848213,-0.08305569,-0.025389139,0.0052901157,0.024774736,-0.034252983,0.022469603,0.006247885,-0.058643,-0.04685419,0.06886175,0.04028137,-0.009991881,-0.02431899,0.067465976,0.048225246,-0.0040247953,0.07361901,-0.03224857,0.008392224