insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('10654719','utility','10654719','US','5/19/2020','Disclosed is a process for the concurrent production of hydrogen and sulphur from a H2S-containing gas stream, with zero emissions. The method comprises the thermal oxidative cracking of H2S so as to form H2 and S2. Preferably, the oxidation is conducted using oxygen-enriched air, preferably pure oxygen. The ratio H2S/O2 in the feedstock is higher than 2:1, preferably in the range of 3:1-5:1.','Zero emissions sulphur recovery process with concurrent hydrogen production','B2',11,'ipg200519.xml',0,'[-0.0073713567,-0.013747761,-0.0043721534,-0.050056163,0.006725805,0.03127617,0.031056669,-0.009466344,0.020382497,-0.017260728,0.0020794393,-0.00019831685,0.070527084,-0.052589558,0.049809646,0.00887686,0.033632047,-0.0805708,0.017786631,0.05494307,0.04337312,-0.10679539,-0.01563021,-0.01794074,0.046322934,-0.051739823,-0.011440353,0.017263921,-0.00807788,0.048371587,-0.007229041,-0.033677038,0.0642493,-0.011316432,-0.0005428042,0.049002975,0.0494202,-0.0026437398,0.0029520048,0.017674545,0.056847233,-0.005323391,0.010654211,-0.0065251724,-0.015895328,0.0541363,-0.020288175,0.051495675,0.10634264,-0.031924035,0.034983996,0.043377798,-0.058334906,-0.029232513,0.044603236,0.012233605,0.03640738,0.05225013,-0.014432464,-0.024626112,-0.042098094,-0.061662544,-0.0054793665,0.010465781,0.009147947,0.04545934,0.06982716,0.06179242,0.007260139,-0.004215625,-0.006268748,0.019326447,0.08605414,-0.013412945,-0.03778925,-0.046170495,0.016034218,-0.02196554,-0.028053505,0.028255872,-0.054310273,0.014708219,-0.037494227,-0.006018665,0.045272745,-0.063518204,-0.00036674688,-0.008123513,0.032609466,0.007051857,-0.0037008037,-0.006013303,0.07345431,0.030277284,0.00852146,-0.01057088,0.028198514,0.0068289707,-0.0018525727,0.00781917,-0.004790825,-0.022387551,-0.008806446,-0.030692669,-0.021493824,0.0613