insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('5069495','utility','5069495','US','12/3/1991','A hand held device for lifting boards such as a sheet or door comprising a support (1) for placing under the edge (5) of the board to be lifted, a body portion (2,3) attached to the support (1) and extending upwardly therefrom and a handle (4) attached to the upper end of the body portion (2,3) for lifting the device so that the board may be carried via the device by an operator. The device further includes a foot mechanism having a foot portion which may be extended from a lower end of the device to engage the ground and a holding mechanism for releasably holding the device in a stable raised position on the extended foot portion and at a desired height and a desired angle wherein the height and the angle of the support relative to the ground are infinitely variable.','Device for lifting boards','A',15,'pftaps19911203_wk49.zip',0,'[-0.021669134,-0.06191844,-0.018104484,-0.011971833,0.035942197,0.012083051,-0.016512899,-0.025243402,0.050952576,0.0071345046,-0.021052744,3.4570326e-06,0.026828805,-0.029162522,0.06643178,0.0062564174,0.05008871,-0.03561656,-0.03006367,-0.052522574,0.020258946,-0.046111085,-0.016125605,0.049982186,0.063019276,-0.074592106,0.027882855,-0.044155825,-0.051793236,0.048481554,-0.04763024,-0.025112137,0.017520368,0.003528432,0.030918008,-0.019091792,0.03277733,0.04279705,0.013495721,0.038507495,0.077120624,-0.059936177,-0.00011812323,-0.08532515,0.018340243,0.024993878,-0.021965591,0.035079915,0.009083963,-0.050297566,0.01048158,0.09811427,0.006300928,-0.0011384941,0.0019670413,0.085144214,0.008039702,0.037128575,0.00042958237,-0.014273415,0.0037471408,-0.036959894,-0.00710028,0.019627143,-0.062293332,0.04088051,-0.0007830018,-0.0063314172,-0.00400145,-0.053844996,0.0012745644,-0.089167364,-0.0023950823,-0.04408816,-0.009145503,-0.03686355,-0.00759127,0.012