insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('5072600','utility','5072600','US','12/17/1991','Apparatus comprising a vessel capable of receiving a variable supply of an aqueous ice slurry in which an upper packed ice bed can float on an aqueous volume; a hollow conduit having a first end located in the lower internal space of the vessel and a second end located exterior of the vessel; a float positioned in the vessel lower internal space; and a movable line in the hollow conduit joined at one end to the float, and the line second end extending out of the conduit second end thus permitting it to be displaced to indicate the position of the float, and thus the bottom of the packed ice bed, when it contacts a packed ice bed bottom.','Wash column ice-pack bottom detection device','A',15,'pftaps19911217_wk51.zip',0,'[-0.022934875,0.02319226,0.011366458,-0.042106148,0.06253903,0.0006813296,0.022162985,0.02201592,0.04185831,0.0038148672,-0.059563186,-0.04927685,0.02537191,-0.054265205,0.038582943,-0.00093085266,0.0404955,-0.016845949,-0.023202064,-0.024933629,-0.006282118,-0.10015122,-0.042983215,-0.0023211061,0.0045433026,-0.10536459,0.010731703,-0.027663458,-0.0736454,-0.014121744,-0.023226906,-0.015498351,0.04195235,-0.023926586,0.008607151,-0.012945365,0.0765728,-0.04318105,-0.020827051,0.046441656,0.046988074,-0.028298123,0.034025934,-0.0736123,-0.032236885,0.0145167485,0.0020511446,0.007021505,0.042803522,-0.05203266,0.005239815,0.046467487,-0.007240913,-0.03386317,0.023120651,0.05786305,0.044182137,0.03418412,0.028829623,-0.012624332,0.036394432,-0.052060682,-0.015567587,0.01544072,-0.07098006,0.051730722,0.036985695,0.05201996,0.055648588,-0.061107874,-0.0116318725,-0.025615621,0.04478855,-0.013966817,-0.020980671,-0.007775246,-0.011743549,0.022567369,-0.04494118,0.065984555,0.01953043,-0.062490683,-0.042918544,-0.025616057,0.028698275,-0.033603657,-0.044024322,-0.051783