insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('5073485','utility','5073485','US','12/17/1991','An immunoassay method which measures test samples at high concentration without dilution is disclosed. Said immunoassay comprises the steps of: (1) reacting a material (A) to be measured, an immobilized component (B) which binds specifically to the material (A), and a labelled component selected from the group consisting of (i) a labelled component (C) which binds specifically to the material (A) and (ii) a labelled component (A) thereby obtaining an immuno-complex and (2) detecting or measuring the labelling fragment, wherein the reaction of the material (A) with the immobilized (B) or the reaction of the material (A) with the immobilized (B) and the labelled component is carried out at a pH of 2-4.5.','Immunoassay method conducted at low pH','A',20,'pftaps19911217_wk51.zip',0,'[-0.023919445,0.009315107,0.027718496,0.010916555,0.03881104,0.006872434,-0.032086626,-0.019882444,0.00061059307,-0.0130933635,-0.053816654,-0.0275353,0.014634923,-0.08537781,-0.016590884,-0.018667908,0.025129234,-0.071031116,-0.014572328,0.022290023,0.006493806,-0.07468409,-0.00066612574,1.32190535e-05,0.02451374,-0.07452722,-0.013140108,-0.027982792,-0.057077885,0.028880514,0.021915648,0.0012540957,0.02227684,0.035629958,-0.0015473595,-0.061131306,0.072997384,-0.030331047,0.056785215,0.013294338,0.042061396,-0.04880294,0.060234096,-0.04019929,-0.025689207,0.007566357,-0.025745941,0.032717112,0.036243353,-0.013083738,0.03028603,0.021074632,0.007987563,-0.04348202,0.018966367,0.027459033,0.007694142,0.045636944,0.0026671006,-0.0026407768,-0.020135669,-0.07323052,0.002756769,0.054362398,0.027630182,0.0497499,0.006589523,0.06056189,-0.022203675,-0.060388837,-0.044143222,-0.010980875,0.04289152,-0.029369222,-0.04109996,-0.061077252,-0.022921547,0.0326913,-0.02751077,0.061420813,-0.037375893,-0.03623048,-0.02