insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('10651791','utility','10651791','US','5/12/2020','A method for determining characteristic parameters of an electrostatic actuation oscillator, where the method includes generating a first excitation voltage defined as being the sum of a first sinusoidal voltage and a voltage pulse; applying the first excitation voltage at the input of the oscillator; acquiring in the time domain a first response voltage present at the output of the oscillator when the first excitation voltage is applied at the input of the oscillator; obtaining, by transformation in the frequency domain, a first amplitude spectral density of the first response voltage; determining the characteristic parameters of the oscillator from the first amplitude spectral density.','Method for determining characteristic parameters of an oscillator','B2',6,'ipg200512.xml',0,'[0.001430505,0.023639036,0.047006644,-0.04248284,-0.0024000844,0.06934786,0.01690392,-0.0062246528,0.055979867,-0.019666022,-0.025562985,0.015159884,0.03278329,-0.062966466,0.038122598,0.02245145,0.008741004,-0.051133677,-0.0041393926,0.023114959,0.03302557,-0.06759573,-0.07829737,0.03496506,0.022017265,-0.032345235,0.0056796796,-0.029166527,-0.057613313,0.069347866,-0.052359723,-0.01677951,0.02987473,-0.0030802255,0.07740627,-0.018023506,0.025338372,-0.0059952266,0.020855043,0.0046466975,0.054211445,-0.02250861,-0.009627572,-0.042880602,-0.006916475,0.03266077,-0.030527778,0.022135248,0.07916463,-0.022100259,0.012735764,0.0038299903,0.029428197,-0.011482052,-0.0011327334,0.015681101,0.03676615,0.104011536,0.0067513525,0.048017584,-0.009004241,-0.060580395,0.027304213,0.052227132,0.0060216635,0.09422007,0.0021117523,0.07274201,0.004219111,-0.0007613056,-0.028416352,-0.0631822,0.06894792,-0.022349546,-0.048781846,-0.0034794807,-0.0132160215,-0.009882613,-0.03961932,0.06689728,-0.011407352,-0.0569312,-0.