insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('10655207','utility','10655207','US','5/19/2020','The Invention relates to an atmospheric-pressure acetylene carburizing furnace, comprises a reaction chamber, an acetylene intake duct, an exhaust gas duct, a control and metering apparatus, an exhaust gas measurement apparatus, and a computer controller. The computer controller calculates a total amount of carbon in the furnace and an enrichment rate of a workpiece, and adjusts an acetylene intake volume according to the calculation result until process requirements are met. The Invention realizes carburizing with acetylene under atmospheric pressure and reduces the usage costs while improving the equipment efficiency.','Atmospheric-pressure acetylene carburizing furnace','B2',7,'ipg200519.xml',0,'[-0.053087477,0.020202884,0.012250543,-0.021991368,0.014016484,0.039323352,-0.005483479,-0.0010984142,0.023695149,0.022561414,-0.05025504,-0.005057474,0.03207136,-0.09574306,0.038161267,0.01805735,0.049122334,-0.0694988,0.010416813,-0.030461295,-0.028706439,-0.054330066,0.00832751,-0.0047811936,-0.017501896,-0.07681245,-0.023629937,-0.012335023,0.0016979307,0.053167738,-0.0049297945,-0.03647202,0.10818946,-0.01849669,-0.016989525,0.008053896,0.036855564,-0.03684036,0.035799794,0.023363056,0.0844459,-0.051895685,0.03421429,0.03991633,-0.02819942,0.046537183,-0.03223104,-0.024196796,0.075246096,-0.049103923,-0.00912033,0.055763863,-0.0091400435,-0.013655654,-0.00028819134,0.046350412,0.0339466,0.050479107,-0.019870242,0.05098531,-0.068474844,-0.08282365,0.00021767164,-0.0017814848,-0.01860474,0.06605245,0.027747752,0.022294072,0.01999418,-0.0075377217,-0.045190502,0.0065368796,0.063305855,0.00904138,0.026228843,-0.0011371272,-0.031717274,0.032951385,-0.03581723,0.026853114,-0.037414443,-0.046974808,-0.11803868,-0.0264395,0.059335697,-0.0478312,-0.04871551,-0.030410081,-0.031349007,-0.01