insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('10658185','utility','10658185','US','5/19/2020','A laser annealing apparatus (1) according to an embodiment includes a laser oscillator (4) configured to generate a laser beam (L), a floating-type conveying stage (3) configured to float and convey a workpiece (W) to be irradiated with the laser beam (L), and a beam profiler (7) configured to measure a beam profile of the laser beam (L). The floating-type conveying stage (3) includes a conveying surface (3a) opposed to the workpiece (W), and a bottom surface (3b) on the side opposite to the conveying surface (3a). The beam profiler (7) is positioned below the bottom surface (3b) of the floating-type conveying stage (3). The floating-type conveying stage (3) includes a detachable part (12) in a part of it. An opening (S) is formed by detaching the detachable part (12) from the floating-type conveying stage (3), the opening (3) extending from the conveying surface (3a) to the bottom surface (3b). The beam profiler (7) is configured to measure the beam profile of the laser beam (L) through the opening (S).','Laser irradiation apparatus, method for manufacturing semiconductor device, and method for operating laser irradiation apparatus','B2',19,'ipg200519.xml',0,'[0.02516475,-0.0032857913,0.051286936,-0.015914395,-0.0014396802,0.0926156,-0.032843404,-0.051225066,0.04637153,0.0063913595,-0.036257166,-0.0044146595,0.036664125,-0.058329724,0.07029639,-0.01607357,0.064608425,-0.053858086,-0.0028762652,-0.042376887,0.0023340993,-0.056161,-0.050945465,-0.0076415357,0.022798648,-0.105560824,0.0093089035,-0.039467372,-0.051860277,0.096421406,-0.000793768,-0.045168065,0.0312747,-0.02743961,0.03276545,-0.03669598,0.020866528,-0.003080028,0.00584099,0.042556286,0.05225243,-0.02858273,0.0702707,-0.06774054,-0.044102572,0.024722707,-0.01747459,0.030460691,0.06687755,-0.03345678,0.016225943,0.06