insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('10658369','utility','10658369','US','5/19/2020','A method for fabricating semiconductor device includes the steps of: providing a substrate having a memory region and a periphery region; forming a first trench and a second trench in substrate on the memory region, wherein a width of the second trench is greater than a width of the first trench; forming a first liner in the first trench and the second trench; forming a second liner on the first liner, wherein the second liner completely fills the first trench and partly fills the second trench; and planarizing the second liner and the first liner to form a first isolation structure and a second isolation structure.','Semiconductor device and method for fabricating the same','B2',9,'ipg200519.xml',0,'[-0.017885434,0.00041299994,0.013257468,-0.038851365,0.00079243234,0.029291872,-0.061971236,0.04340491,0.024819348,-0.020083906,-0.03078071,-0.0017754897,0.018019864,-0.045847237,0.033350714,-0.017364541,0.034029506,-0.052966326,0.0034618713,0.020441378,0.07002987,-0.01879094,-0.058892794,0.047607146,0.027618349,-0.11258175,0.045539096,-0.0024123406,-0.02507183,0.05522522,0.0077193626,-0.033474244,0.00528369,-0.020067748,0.0059606903,-0.017409012,0.0060295593,-0.008690041,0.032611933,0.007117332,0.07844622,-0.021946775,0.00616898,-0.036268476,-0.074645154,0.036922753,-0.056954715,0.05460588,0.024308007,-0.02674191,0.025469055,0.048708074,-0.0073967325,-0.054864205,0.023908501,0.026707366,-0.0034887642,0.063374445,0.002865262,0.02635722,-0.03980204,-0.0041324217,-0.02362499,-0.008844632,-0.058451284,0.056539677,0.040102523,0.036170952,0.01523887,-0.031011358,-0.04024583,-0.022951135,0.074249476,-0.018904172,0.004227234,-0.006567349,-0.004362222,-0.003624192,-0.014453506,0.058068916,-0.027623916,-0.052735277,-0.016727569,-0.0083497,0.06670121,0.049104393,-0.0037187827,-0.036097612,0.0