insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('10658563','utility','10658563','US','5/19/2020','An ultrasound transducer used in an ultrasound system and a manufacturing method thereof includes: a backing block; a piezoelectric layer placed on the backing block; a matching layer placed on the piezoelectric layer; and a ground layer placed between the piezoelectric layer and the matching layer. The backing layer includes a connector that connects a transmitting unit and a receiving unit of an ultrasound system, and a wiring area that connects the piezoelectric layer and the connector. The wiring area is formed by etching and filling with metal material.','Ultrasound transducer and manufacturing method thereof','B2',6,'ipg200519.xml',0,'[-0.01276185,0.045008708,0.059692997,-0.06569698,-0.009277115,0.011019711,-0.016875608,-0.011420937,0.03679102,-0.009185357,-0.021091504,0.010280321,0.048690185,-0.084607296,0.06392569,-0.024827702,0.04509062,-0.07869299,0.004049376,-0.023062441,-0.0152925765,-0.06658682,-0.08015065,0.018395271,0.026708439,-0.08790945,0.00684234,-0.028026978,-0.028227977,0.07437223,0.029604925,-0.01869036,0.05034241,-0.019194687,0.027590744,-0.03429722,0.035268936,-0.028118301,0.041231066,0.0039043117,0.018242748,-0.004364204,0.07149144,0.0074351323,-0.046216026,0.06296828,-0.02897225,0.022315701,0.02507426,-0.0021798383,0.0260504,0.067398034,0.022604354,-0.085173555,0.007794516,-0.0021193696,0.032035597,0.07064004,0.012821271,-0.021561973,0.05950969,-0.028964767,0.005031032,0.012020398,-0.05376382,0.049199603,0.044169784,0.076679625,-0.0017460466,-0.02094422,-0.028406547,-0.02927283,0.042564243,-0.031317987,-0.0585291,-0.020702899,-0.001694948,-0.004065079,-0.036208738,0.09584211,-0.03701371,-0.031334627,-0.055002153,0.010870335,0.04077082,0.0038251346,-0.041528042,0.009856543,0.024767233,0.013194285,0.031575195,-0.022999028,-0.024231357,0.002073505,0.017343