insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('10660721','utility','10660721','US','5/26/2020','A modular wrist guide is provided that aids a user in operating a hand-held surgical instrument to accurately perform surgical procedures including but not limited to joint arthroplasty. The modular wrist guide acts to constrain the orientation of a hand-held surgical instrument, or a users wrist relative to the users forearm to perform a procedure according to a surgical plan. A forearm embracing member is designed to secure the users forearm to the modular wrist guide.','Modular wrist guide for surgical instruments','B2',43,'ipg200526.xml',0,'[-0.047779664,-0.014365546,-0.00042488717,-0.012956241,0.024145754,0.077913694,0.0037955104,-0.041171327,0.03688945,-0.031660303,-0.009689574,0.013021891,0.066006675,-0.07718533,0.08163596,-0.016747693,0.058992747,-0.078171834,0.024768852,-0.016268661,0.007148715,-0.029227244,-0.045247335,0.0791985,0.06051177,-0.06626475,0.028074209,-0.023998665,-0.021326095,0.033293094,-0.047736045,-0.04032521,0.059384253,0.02731445,-0.007162027,-0.028682573,0.026014559,0.007301387,0.011236535,0.03062513,0.06743768,-0.053175487,0.023024814,-0.021419076,0.039530523,0.045107685,-0.046074163,0.059790887,0.024253251,-0.059815884,0.068861656,0.068419725,-0.012524275,-0.017294401,0.053774964,0.030570911,0.007928469,0.02831426,-0.001907386,0.002526851,0.022658061,-0.021057531,-0.009888985,0.0112900315,-0.04910547,0.08007753,-0.0074564912,0.038330056,-0.0060377293,-0.049451,0.002482835,-0.03913548,-0.00047601783,-0.038896028,0.008787402,0.007972759,-0.025081238,-0.00080671284,-0.06859023,0.07360176,-0.044451535,-0.04610705,-0.073368505,-0.02216519,0.032058105,-0.029701794,-0.04731,-0.04372208,0.028705295,-0.00093789434,0.015011452,-0.009569707,0.043999776,-0.043043677,0.057158437,0.010266156,0.027902417,0.030580558,0.025375085,0.0020661587,0.018362679,0.03469645