insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('10679524','utility','10679524','US','6/9/2020','An adornment for a motorcycle engine is provided. The adornment includes a main body having a front surface and an opposite rear surface, the front surface including a recessed area for receiving a face plate having words, graphics or other indicia disposed thereon. The rear surface includes one or more attachment mechanisms for attaching the adornment to a selected region of the motorcycle engine. The rear surface has a contour complimentary to said selected region of said motorcycle engine.','Motorcycle engine adornment','B1',16,'ipg200609.xml',0,'[-0.053213008,0.02316498,0.041502018,-0.028145846,-0.03783363,0.03379309,-0.04271737,-0.010353672,0.038840685,-0.04610178,-0.10680054,-0.0015252746,0.022046419,-0.08755662,-0.024224767,0.0135555,0.045486882,-0.039706837,0.030011708,-0.027156616,0.03009682,-0.025500193,-0.05260144,0.028908826,0.06942465,-0.0437006,-0.01571322,-0.022067435,-0.038725518,0.065128595,0.013946575,-0.102175884,0.09194942,0.07745718,0.0036703474,-0.045539986,0.029255986,0.015585979,0.02068825,0.026016947,0.060360834,-0.05462601,-0.014278428,-0.04865514,-0.03176819,0.03573608,-0.011188815,-0.032276712,0.011493644,-0.021415504,0.0018191877,0.07034807,0.0005888584,-0.07781726,0.035528135,0.05300255,0.006565271,0.01159706,-0.04660976,0.024114683,0.018327584,-0.033761792,-0.012602902,-0.005161884,-0.036574364,0.013180778,0.06543275,-0.005657587,0.006675837,0.0053695864,0.013875478,-0.020582713,0.01260353,0.012608844,-0.046785336,0.037842464,0.0065436764,0.051400445,-0.06043802,0.07384886,-0.013814755,-0.028304858,-0.033332758,-0.051157173,-0.0074934345,-0.016317282,-0.009235535,-0.064675525,0.010426099,0.059623376,0.04749919,-0.017585024,0.0012194683,0.0036124901,0.043952346,-0.0109709045,0.037482906,0.06153089,-0.028332813,0.00044719534,0.05069968,0.016661657,-0.