insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('8800609','utility','8800609','US','8/12/2014','A bib for a vehicle fuel tank inlet conduit of the type having an open conduit end comprises a liquid-impervious, elongated tray that has a raised peripheral edge on a front side thereof. The bib includes a top end, a bottom end, and an aperture at the top end for receiving the conduit end therethrough. The bib includes a collection trough at the front side and bottom end thereof that is adapted to receive fuel flowing down the tray, and may include an inverted spout formed between the aperture and the collection trough.','Fuel bib','B1',14,'ipg140812.xml',0,'[-0.0015920341,0.028185131,-0.010583351,-0.03378778,-0.016002307,0.038206987,-0.020494623,0.030097809,0.022447823,0.009182137,-0.089430526,-0.014865399,0.07968564,-0.04695204,0.0030993223,-0.010534707,0.049025897,-0.0030040494,0.011897339,-0.037554953,0.007675771,-0.06930977,-0.044832595,0.038912747,0.05102885,-0.06972012,0.015599818,-0.019548865,-0.035120767,0.06579724,0.00491503,-0.055514727,0.024328666,0.008316918,-0.0038029405,-0.034673024,0.017436026,0.013351894,-0.04498248,0.070389874,0.038589235,-0.017175974,-0.0042278403,0.0018645818,-0.03098425,0.009976084,0.0014628512,-0.022627484,-0.008058721,-0.09200439,0.018622315,0.043897692,-0.007544603,-0.071818575,0.035775382,0.012582819,0.02429458,0.019376235,-0.032559965,-0.0034229704,-0.01133013,-0.049888525,-0.08760797,0.00022116282,-0.07898966,0.037951484,0.022218961,0.020805962,0.037293904,-0.027459864,0.018597053,-0.016143426,0.036862776,-0.033598054,0.02212445,-0.04717842,0.029866165,0.0675727,-0.051540386,0.036230136,0.025758222,-0.009131792,-0.03169544,-0.002032252,0.06029417,-0.03831617,-0.02742133,-0.057163276,0.01162128,0.009494275,0.0175534,-0.012609153,0.015718058,-0.0045051747,0.027593559,0.0006438071,-0.000802308,0.07086973,0.006830841,0.01787895,0.04634541,0