insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('10676167','utility','10676167','US','6/9/2020','A boat lift includes four posts and four linear actuators, each attached to one of the posts. Each linear actuator includes an extendable and retractable member oriented for extension and retraction substantially parallel to the post. Ends of a first pair of the extendable and retractable members are connected to a first carrier and ends of a second pair of the extendable and retractable members are connected to a second carrier. A cradle or platform is supported by the first and second carriers. The boat lift may be supported by the ground, by a structure, for example, a dock, a sea wall or a wall of a boat house, or by pontoons.','Boat lift','B2',16,'ipg200609.xml',0,'[0.023660474,0.018682014,0.0135578895,-0.020976221,0.06676783,0.0157769,0.01245924,-0.01067008,0.0015688228,0.021136586,-0.02697107,0.021922579,0.06259998,-0.03441091,0.04566834,0.059439916,0.047693532,-0.040904544,-0.040067807,-0.050254684,0.037839454,-0.03400285,-0.04457155,0.032382526,0.027726991,-0.08856885,-0.0070579057,-0.06181782,-0.041235957,0.007242919,0.011107078,-0.02857868,0.0568648,-0.013370401,0.0193104,-0.021553516,-0.0069728782,0.009622284,-0.018900484,-0.011802722,0.031199325,-0.023710184,0.035305444,-0.03989809,-0.03656399,0.059058025,-0.049643025,0.023816423,0.012000565,-0.043804433,0.033669252,0.08885302,0.03620163,0.010124526,0.022638634,0.0698009,-0.006428803,-0.00065253355,-0.056452774,0.032375373,3.0631647e-05,0.00735197,0.0054123304,-0.0078086886,-0.0467528,0.064876005,-0.01857905,0.029772632,0.0145526435,-0.0038389151,-0.00974322,-0.090830065,0.04834407,-0.075043365,-0.019419877,-0.032921396,0.017744845,0.01878353,-0.012140676,0.07512968,-0.016180996,-0.031134391,-0.029264292,-0.016548937,-0.004143546,-0.061208133,0.017359003,-0.030807437,-0.011213023,0.008802049,0.026325153,-0.028447988,