insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('10677504','utility','10677504','US','6/9/2020','Disclosed is an evaporator for an ice maker including: a refrigerant pipe having a circular cross-section, with refrigerant flowing therethrough; and a pair of ice making plates disposed on opposite sides of the refrigerant pipe. The refrigerant pipe is disposed between inner side surfaces of the ice making plates facing each other, and rounded parts are provided by being formed outwards at a place where the refrigerant pipe is located such that the rounded parts cover both sides of the refrigerant pipe by being in close contact therewith.','Evaporator for ice maker','B2',9,'ipg200609.xml',0,'[-0.020201657,0.0357867,0.05294003,-0.066631466,-0.020747313,0.041507404,0.014052915,0.033484444,0.02172383,-0.043862347,-0.0062402366,-0.055471957,0.025170723,-0.06657873,0.026289888,-0.01204296,0.05126949,-0.045850687,-0.022075217,-0.0027828189,0.025858028,-0.076778814,-0.008119221,0.0030329905,0.03693953,-0.08866324,0.02314527,0.015628485,-0.01703141,0.03484948,0.031343814,-0.020981168,0.086050324,-0.04315213,-0.004451904,-0.075582676,0.01627773,-0.018088566,-0.016700363,0.04338202,0.051704004,-0.024418358,0.00153367,-0.061275933,-0.03811391,0.06258656,-0.012426742,-0.004167135,-0.0071242345,-0.020283503,0.022651572,0.045508184,0.005468427,-0.09452327,0.017477205,0.067676105,0.0004910836,0.07053055,-0.03565623,-0.030980896,0.014650374,-0.0329897,-0.012277059,0.009792695,-0.08568494,0.032534245,0.034000874,0.038692534,0.06372157,-0.0674758,-0.0258252,0.0052875187,0.030579958,-0.03886548,0.011504416,-0.029574813,-0.02563655,0.014266979,-0.05711602,0.06630974,-0.016267309,-0.022176072,-0.02679078,-0.043622505,0.013264599,-0.050194394,-0.0038828084,-0.013664622,0.006692867,0.02317937,-0.008280933,-0.06549181,0.04028612,-0.026336724,0.015163856,0.05217092,0.028040558,0.049681973,-0.008470396,0