insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('10678255','utility','10678255','US','6/9/2020','Systems, Methods and Apparatuses are provided for detecting surface conditions, which includes: an image scene captured by a camera wherein the image scene includes: a set of a plurality of regions of interest (ROIs); and a processor configured to receive the image scene to: extract at least a first and a second ROI from the set of the plurality of ROIs of the image scene; associate the first ROI with an above-horizon region and associate the second ROI with a surface region; analyze the first ROI and the second ROI in parallel for a condition related to an ambient lighting in the first ROI and for an effect related to the ambient lighting in the second ROI; and extract from the first ROI features of the condition of the ambient lighting and extract from the second ROI features of the effect of the ambient lighting on a surface region.','Systems, methods and apparatuses are provided for enhanced surface condition detection based on image scene and ambient light analysis','B2',19,'ipg200609.xml',0,'[-0.026240414,-0.04988719,0.027310247,0.03483232,-0.02244217,0.05839876,0.030919528,-0.0031304155,0.06115449,-0.0300765,-0.03536244,0.011737241,0.024325524,-0.03457773,-0.006819711,0.017626869,0.016921755,-0.099603735,-0.0006569762,-0.06704988,0.027882004,-0.061342373,-0.041817687,-0.018987127,0.037056457,-0.07820335,0.011463711,0.0005189545,-0.053998936,0.054215774,-0.008171173,0.010011557,0.0528785,0.028208226,-0.00864005,0.03769055,0.057097875,0.011155537,0.05659391,0.020598253,0.06870228,-0.027802188,0.0016089325,-0.064992584,-0.06555972,0.03537992,-0.06163204,-0.0070390743,-0.007573733,-0.06497374,0.00655923,0.007077475,-0.004203965,-0.0029139367,0.031762805,0.09649896,0.014971237,0.021129072,0.014332779,-0.010827114,0.024952866,-0.006997861,0.01757087,0.0018643702,-0.06055532,0.01