insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('5948502','utility','5948502','US','9/7/1999','An improved tanning system involves the use of a film of material which is permeable to ultra-violet light and which is adapted to be laid on part of a human body, for example the torso. The film is covered in certain desired regions with a material which is impermeable to ultra-violet light which regions are surrounded by regions which are only slightly permeable to ultra-violet light. When a person wearing the film is subjected to tanning, the result is improved appearance of the torso, for example, the person may look fitter, slimmer and/or more muscular. The tanning may be achieved by either natural sunlight or by means of a sunbed.','Tanning systems','A',6,'pftaps19990907_wk36.zip',0,'[-0.030629992,-0.03378928,0.03341676,-0.017945822,-0.020337353,0.03942439,0.023055874,0.0034780374,0.03981394,-0.0063381344,-0.019764356,-0.034526195,0.071959,-0.033273965,0.040599126,0.0041370797,0.037159704,-0.05358806,0.007147202,0.0015444697,0.042158484,-0.043290567,-0.066443756,0.006896729,0.050574973,-0.059747133,-0.0076271747,-0.03233377,-0.047027156,0.0063665616,-0.012408762,-0.03756917,0.045866583,0.019239565,-0.029943464,-0.013592665,-0.011152101,0.03823416,0.04517764,0.02210213,0.06728758,-0.015459932,0.006935277,-0.058979955,-0.0691554,0.020918101,-0.046312626,0.001336773,0.032409985,-0.058691517,-0.01080301,0.04455412,-0.041349087,0.0021691166,0.06268762,0.037781265,0.0025805517,0.045029085,-0.047535915,-0.025153726,-0.008957621,0.002128621,0.027513532,0.02073157,-0.04861624,0.06570955,0.050731573,0.05874099,0.014821955,-0.056669652,0.02715101,-0.017769521,0.05229036,-0.052222166,-0.0057796347,0.008854264,0.037635125,0.0045023435,-0.0115605695,0.087388285,-0.06446277,-0.030172108,-0.031971514,-0.0018235978,-0.027522875,-0.026122583,0.00822663,-0.046895057,0.061686095,-0.009366773,0.0