insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('5955107','utility','5955107','US','9/21/1999','Rapidly disintegrating and readily suspendible tablets and their method of preparation are disclosed in which there is a therapeutic amount of a pharmacologically active ingredient, 1 to 6 percent croscarmellose sodium, 10 to 50 percent microcrystalline cellulose, and 10 to 50 percent of a coprocessed additive consisting essentially of 75 to 95 percent microcrystalline cellulose and 5 to 25 percent calcium, sodium alginate complex. The tablets are suitable for oral administration of measured-dose suspensions of either water soluble or water insoluble pharmaceuticals.','Pharmaceutical suspension tablet compositions','A',14,'pftaps19990921_wk38.zip',0,'[0.00934927,0.0039170976,-0.02051293,-0.03669028,-0.017046683,0.06369004,-0.012213625,0.03942043,0.017007932,0.012970205,-0.02734756,0.030225568,0.05036484,-0.09626353,0.073689334,-0.031146834,-0.008314025,-0.038795482,0.025293754,0.015375012,0.00932195,-0.05055003,-0.012357766,0.03536091,0.0047536124,-0.029963057,-0.05008273,0.00886607,-0.030805735,0.050340332,0.020623917,0.02791436,0.10775232,-0.024743585,0.010962825,-0.03618841,0.032557905,-0.004433985,-0.0048702643,-0.009166067,0.041915283,-0.019178754,-0.0204907,-0.035472132,0.0012482252,0.024959605,0.022220915,0.004964977,0.052107826,0.007012329,0.018806897,0.03419732,-0.024714392,0.022566264,0.07796631,-0.008797156,-0.013714306,0.048060097,-0.043285076,0.015877988,0.008062787,-0.040236507,0.011405829,0.013514745,-0.013094985,0.0027302203,0.044009816,-0.011842324,0.033620223,-0.038883362,-0.02204012,0.0072547076,0.0018669583,0.008707828,-0.012007185,-0.08528963,0.07050998,0.04216322,-0.015828032,0.095546536,0.013780031,-0.074599914,-0.054922827,-0.0365013,-0.060329538,-0.07708878,-0.045292504,-0.004814773,-0.019459968,0.018592589,-0.050391287,0.032184776,0.07162591,-0.04788551,-